import { useAuth } from "@/hooks/useAuth";
import AppHeader from "@/components/AppHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { LogOut } from "lucide-react";
import AccountInfoCard from "@/components/settings/AccountInfoCard";
import EmailInboxCard from "@/components/settings/EmailInboxCard";
import ChangePasswordCard from "@/components/settings/ChangePasswordCard";
import UsageHistoryCard from "@/components/settings/UsageHistoryCard";
import PaymentHistoryCard from "@/components/settings/PaymentHistoryCard";

const Settings = () => {
  const { signOut } = useAuth();

  return (
    <div className="min-h-screen bg-background">
      <AppHeader />
      <main className="mx-auto max-w-2xl px-4 py-8 space-y-6">
        <h1 className="text-2xl font-bold text-foreground">Account Settings</h1>
        <AccountInfoCard />
        <EmailInboxCard />
        <ChangePasswordCard />
        <UsageHistoryCard />
        <PaymentHistoryCard />
        <Card className="border-destructive/30">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg text-destructive">
              <LogOut className="h-5 w-5" />
              Danger Zone
            </CardTitle>
          </CardHeader>
          <CardContent>
            <Button variant="destructive" onClick={signOut}>
              Sign out
            </Button>
          </CardContent>
        </Card>
      </main>
    </div>
  );
};

export default Settings;

