import { useState, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Coins, History, Zap } from "lucide-react";

interface UsageLog {
  id: string;
  created_at: string;
  credits_used: number;
  job_id: string | null;
  job_title?: string | null;
}

const PAGE_SIZE = 10;

const UsageHistoryCard = () => {
  const { user } = useAuth();
  const [usageLogs, setUsageLogs] = useState<UsageLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);

  const fetchLogs = async (pageNum: number, append = false) => {
    if (!user) return;
    if (pageNum === 0) setLoading(true);
    else setLoadingMore(true);

    const { data } = await supabase
      .from("usage_logs")
      .select("id, created_at, credits_used, job_id")
      .eq("user_id", user.id)
      .order("created_at", { ascending: false })
      .range(pageNum * PAGE_SIZE, (pageNum + 1) * PAGE_SIZE - 1);

    if (data) {
      setHasMore(data.length === PAGE_SIZE);
      const jobIds = [...new Set(data.map(l => l.job_id).filter(Boolean))] as string[];
      let jobTitles: Record<string, string | null> = {};
      if (jobIds.length > 0) {
        const { data: jobs } = await supabase.from("jobs").select("id, title").in("id", jobIds);
        if (jobs) jobs.forEach(j => { jobTitles[j.id] = j.title; });
      }
      const mapped = data.map(l => ({
        ...l,
        job_title: l.job_id ? (jobTitles[l.job_id] ?? "Untitled Job") : null,
      }));
      setUsageLogs(prev => append ? [...prev, ...mapped] : mapped);
    }
    setLoading(false);
    setLoadingMore(false);
  };

  useEffect(() => {
    fetchLogs(0);
  }, [user]);

  const loadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
    fetchLogs(nextPage, true);
  };

  return (
    <Card className="overflow-hidden">
      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
          <History className="h-4.5 w-4.5 text-primary" />
        </div>
        <div>
          <h3 className="text-base font-semibold text-foreground">Usage History</h3>
          <p className="text-xs text-muted-foreground">Your credit deductions.</p>
        </div>
      </div>
      <CardContent className="px-6 pt-3 pb-5">
        {loading ? (
          <div className="space-y-3">
            {[...Array(4)].map((_, i) => (
              <Skeleton key={i} className="h-12 w-full rounded-lg" />
            ))}
          </div>
        ) : usageLogs.length === 0 ? (
          <div className="text-center py-10">
            <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-accent">
              <Zap className="h-6 w-6 text-muted-foreground/40" />
            </div>
            <p className="text-sm text-muted-foreground">
              No credit usage yet. Start ranking resumes to see your history here.
            </p>
          </div>
        ) : (
          <div className="space-y-1">
            {usageLogs.map((log) => (
              <div
                key={log.id}
                className="flex items-center justify-between rounded-lg px-3 py-2.5 hover:bg-accent/50 transition-colors"
              >
                <div className="min-w-0">
                  <p className="text-sm font-medium text-foreground truncate">
                    {log.job_title ?? "No job linked"}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {new Date(log.created_at).toLocaleDateString("en-US", {
                      month: "short", day: "numeric", year: "numeric",
                      hour: "2-digit", minute: "2-digit"
                    })}
                  </p>
                </div>
                <Badge variant="secondary" className="gap-1 shrink-0 tabular-nums">
                  <Coins className="h-3 w-3" />
                  -{log.credits_used}
                </Badge>
              </div>
            ))}
          </div>
        )}
        {!loading && usageLogs.length > 0 && hasMore && (
          <div className="pt-3 text-center">
            <Button variant="outline" size="sm" onClick={loadMore} disabled={loadingMore}>
              {loadingMore ? "Loading…" : "Load more"}
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default UsageHistoryCard;

