import { useState, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { CreditCard, Receipt } from "lucide-react";

interface Payment {
  id: string;
  created_at: string;
  amount: number;
  currency: string;
  credits_purchased: number;
  status: string;
  dodo_payment_id: string | null;
  plan_id: string | null;
}

const PAGE_SIZE = 10;

const PaymentHistoryCard = () => {
  const { user } = useAuth();
  const [payments, setPayments] = useState<Payment[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(0);
  const [hasMore, setHasMore] = useState(false);
  const [loadingMore, setLoadingMore] = useState(false);

  const fetchPayments = async (pageNum: number, append = false) => {
    if (!user) return;
    if (pageNum === 0) setLoading(true);
    else setLoadingMore(true);

    const { data } = await supabase
      .from("payments")
      .select("id, created_at, amount, currency, credits_purchased, status, dodo_payment_id, plan_id")
      .eq("user_id", user.id)
      .order("created_at", { ascending: false })
      .range(pageNum * PAGE_SIZE, (pageNum + 1) * PAGE_SIZE - 1);

    if (data) {
      setHasMore(data.length === PAGE_SIZE);
      setPayments(prev => append ? [...prev, ...data] : data);
    }
    setLoading(false);
    setLoadingMore(false);
  };

  useEffect(() => {
    fetchPayments(0);
  }, [user]);

  const loadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
    fetchPayments(nextPage, true);
  };

  const statusVariant = (status: string): "success" | "warning" | "destructive" | "secondary" => {
    switch (status) {
      case "paid": return "success";
      case "created": return "warning";
      case "failed": return "destructive";
      default: return "secondary";
    }
  };

  const statusLabel = (status: string) => {
    switch (status) {
      case "paid": return "Successful";
      case "created": return "Unpaid";
      case "failed": return "Failed";
      case "dismissed": return "Cancelled";
      default: return "Pending";
    }
  };

  return (
    <Card className="overflow-hidden">
      <div className="flex items-center gap-3 px-6 pt-5 pb-2">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
          <CreditCard className="h-4.5 w-4.5 text-primary" />
        </div>
        <div>
          <h3 className="text-base font-semibold text-foreground">Payment History</h3>
          <p className="text-xs text-muted-foreground">Your recent purchases.</p>
        </div>
      </div>
      <CardContent className="px-6 pt-3 pb-5">
        {loading ? (
          <div className="space-y-3">
            {[...Array(3)].map((_, i) => (
              <Skeleton key={i} className="h-12 w-full rounded-lg" />
            ))}
          </div>
        ) : payments.length === 0 ? (
          <div className="text-center py-10">
            <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-full bg-accent">
              <Receipt className="h-6 w-6 text-muted-foreground/40" />
            </div>
            <p className="text-sm text-muted-foreground">
              No purchases yet. Buy credits to see your payment history here.
            </p>
          </div>
        ) : (
          <div className="space-y-1">
            {payments.map((p) => (
              <div
                key={p.id}
                className="flex items-center justify-between rounded-lg px-3 py-2.5 hover:bg-accent/50 transition-colors"
              >
                <div className="min-w-0">
                  <p className="text-sm font-medium text-foreground">
                    {p.credits_purchased} credits
                    <span className="ml-1.5 text-[11px] font-normal text-muted-foreground">
                      {p.plan_id ? "Subscription" : "Top-up"}
                    </span>
                  </p>
                  <p className="text-xs text-muted-foreground truncate">
                    {new Date(p.created_at).toLocaleDateString("en-US", {
                      month: "short", day: "numeric", year: "numeric",
                      hour: "2-digit", minute: "2-digit"
                    })}
                  </p>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <span className="text-sm font-semibold tabular-nums text-foreground">
                    {p.currency} {(p.amount / 100).toFixed(2)}
                  </span>
                  <Badge variant={statusVariant(p.status)}>{statusLabel(p.status)}</Badge>
                </div>
              </div>
            ))}
          </div>
        )}
        {!loading && payments.length > 0 && hasMore && (
          <div className="pt-3 text-center">
            <Button variant="outline" size="sm" onClick={loadMore} disabled={loadingMore}>
              {loadingMore ? "Loading…" : "Load more"}
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default PaymentHistoryCard;

