import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
    const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;

    const authHeader = req.headers.get("Authorization");
    if (!authHeader) throw new Error("No auth");

    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
      global: { headers: { Authorization: authHeader } },
    });
    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    if (userError || !user) throw new Error("Unauthorized");
    const userId = user.id;

    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", userId);
    if (!roles?.some((r: any) => r.role === "admin")) {
      return new Response(JSON.stringify({ error: "Admin access required" }), {
        status: 403, headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const body = await req.json();
    const { key_name } = body;

    // ─── DNS MX record check ───
    if (key_name === "DNS_MX_CHECK") {
      const domain = body.domain;
      if (!domain) throw new Error("Missing domain");

      try {
        // Use Google DNS-over-HTTPS API to check MX records
        const dnsRes = await fetch(`https://dns.google/resolve?name=${encodeURIComponent(domain)}&type=MX`);
        const dnsData = await dnsRes.json();

        const mxRecords: { exchange: string; priority: number }[] = [];
        let pointsToExpected = false;

        if (dnsData.Answer && Array.isArray(dnsData.Answer)) {
          for (const answer of dnsData.Answer) {
            if (answer.type === 15) { // MX record type
              const parts = answer.data.split(" ");
              const priority = parseInt(parts[0], 10);
              const exchange = (parts[1] || "").replace(/\.$/, "").toLowerCase();
              mxRecords.push({ exchange, priority });
              // Accept any valid MX record pointing to a known email provider
              if (exchange.includes("inbound.postmarkapp.com") || exchange.includes("resend") || exchange.includes("mx")) {
                pointsToExpected = true;
              }
            }
          }
        }

        return new Response(JSON.stringify({
          status: mxRecords.length > 0 ? "success" : "no_records",
          domain,
          mx_records: mxRecords,
          points_to_expected: pointsToExpected,
        }), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      } catch (e: unknown) {
        return new Response(JSON.stringify({
          status: "error",
          error: e instanceof Error ? e.message : String(e),
        }), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
    }

    if (!key_name) throw new Error("Missing key_name");

    let status = "failed";
    let errorMsg = "";
    let details: Record<string, any> = {};

    if (key_name === "OPENAI_API_KEY") {
      const openaiKey = Deno.env.get("OPENAI_API_KEY");
      if (!openaiKey) {
        errorMsg = "OPENAI_API_KEY secret is not configured";
      } else {
        try {
          const res = await fetch("https://api.openai.com/v1/models", {
            headers: { Authorization: `Bearer ${openaiKey}` },
          });
          if (res.ok) {
            status = "success";
          } else {
            const body = await res.text();
            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
          }
        } catch (e: unknown) {
          errorMsg = e instanceof Error ? e.message : String(e);
        }
      }
    } else if (key_name === "RAZORPAY_KEY_ID") {
      const razorpayKeyId = Deno.env.get("RAZORPAY_KEY_ID");
      const razorpayKeySecret = Deno.env.get("RAZORPAY_KEY_SECRET");
      if (!razorpayKeyId || !razorpayKeySecret) {
        errorMsg = "RAZORPAY_KEY_ID or RAZORPAY_KEY_SECRET secret is not configured";
      } else {
        try {
          const res = await fetch("https://api.razorpay.com/v1/payments?count=1", {
            headers: {
              Authorization: "Basic " + btoa(`${razorpayKeyId}:${razorpayKeySecret}`),
            },
          });
          if (res.ok) {
            status = "success";
          } else {
            const body = await res.text();
            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
          }
        } catch (e: unknown) {
          errorMsg = e instanceof Error ? e.message : String(e);
        }
      }
    } else if (key_name === "RESEND_API_KEY") {
      // Read API key from platform_config (stored in DB, not env vars)
      const { data: config } = await supabase
        .from("platform_config")
        .select("resend_api_key, email_from_address")
        .limit(1)
        .single();

      const apiKey = config?.resend_api_key;
      if (!apiKey) {
        errorMsg = "Resend API key is not configured. Add it in Email Settings.";
      } else {
        try {
          // Validate API key by listing domains
          const domainsRes = await fetch("https://api.resend.com/domains", {
            headers: {
              "Authorization": `Bearer ${apiKey}`,
              "Content-Type": "application/json",
            },
          });
          const domainsBody = await domainsRes.text();

          if (!domainsRes.ok) {
            errorMsg = `Invalid API key (${domainsRes.status})`;
            details.keyValid = false;
          } else {
            details.keyValid = true;

            try {
              const domainsData = JSON.parse(domainsBody);
              const domains = domainsData.data || [];
              details.totalDomains = domains.length;

              // Check if from address domain is verified
              const fromEmail = config?.email_from_address || "noreply@rankora.co";
              details.fromEmail = fromEmail;
              const fromDomain = fromEmail.split("@")[1]?.toLowerCase();

              const domainMatch = domains.find((d: any) =>
                d.name?.toLowerCase() === fromDomain
              );

              if (domainMatch) {
                details.domainVerified = domainMatch.status === "verified";
                details.domainName = domainMatch.name || "";
              } else {
                details.domainVerified = false;
                details.domainName = "";
              }
            } catch { details.domainVerified = false; }

            status = "success";
          }
        } catch (e: unknown) {
          errorMsg = e instanceof Error ? e.message : String(e);
        }
      }
    } else if (key_name === "GEMINI_API_KEY") {
      const geminiKey = Deno.env.get("GEMINI_API_KEY");
      if (!geminiKey) {
        errorMsg = "GEMINI_API_KEY secret is not configured";
      } else {
        try {
          const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${geminiKey}`);
          if (res.ok) {
            status = "success";
            const body = await res.json();
            details.modelsCount = body.models?.length || 0;
          } else {
            const body = await res.text();
            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
          }
        } catch (e: unknown) {
          errorMsg = e instanceof Error ? e.message : String(e);
        }
      }
    } else if (key_name === "DODO_PAYMENTS_API_KEY") {
      const dodoKey = Deno.env.get("DODO_PAYMENTS_API_KEY");
      if (!dodoKey) {
        errorMsg = "DODO_PAYMENTS_API_KEY secret is not configured";
      } else {
        try {
          // Read environment from platform_config (UI-editable) or fall back to env var
          const { data: cfg } = await supabase
            .from("platform_config")
            .select("dodo_payments_environment")
            .limit(1)
            .single();
          const dodoEnv = (cfg as any)?.dodo_payments_environment
            || Deno.env.get("DODO_PAYMENTS_ENVIRONMENT")
            || "test_mode";
          const dodoBaseUrl = dodoEnv === "live_mode"
            ? "https://live.dodopayments.com"
            : "https://test.dodopayments.com";

          const res = await fetch(`${dodoBaseUrl}/payments?page_size=1`, {
            headers: { Authorization: `Bearer ${dodoKey}` },
          });
          if (res.ok) {
            status = "success";
            details.environment = dodoEnv;
          } else {
            const body = await res.text();
            errorMsg = `API returned ${res.status}: ${body.slice(0, 200)}`;
          }
        } catch (e: unknown) {
          errorMsg = e instanceof Error ? e.message : String(e);
        }
      }
    } else {
      errorMsg = `Unknown integration: ${key_name}`;
    }

    // Update integrations table
    await supabase.from("integrations").update({
      last_tested_at: new Date().toISOString(),
      last_test_status: status,
      is_configured: status === "success",
    }).eq("key_name", key_name);

    return new Response(JSON.stringify({ status, error: errorMsg || undefined, details }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err: unknown) {
    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
      status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

