  5→// No wildcard CORS — this is a server-to-server webhook endpoint.
  6→// Only allow OPTIONS for health checks with restrictive headers.
  7→const corsHeaders = {
  8→  "Access-Control-Allow-Origin": "",
  9→  "Access-Control-Allow-Methods": "POST, OPTIONS",
 10→  "Access-Control-Allow-Headers": "content-type",
 11→};
