 40→/**
 41→ * Verify webhook signature using HMAC-SHA256.
 42→ * Supports X-Webhook-Signature header or a shared secret via query param.
 43→ */
 44→async function verifyWebhookSignature(req: Request, body: ArrayBuffer): Promise<boolean> {
 45→  const secret = Deno.env.get("EMAIL_INGEST_WEBHOOK_SECRET");
 46→  if (!secret) {
 47→    // If no secret is configured, reject all requests for safety.
 48→    // Operators must set EMAIL_INGEST_WEBHOOK_SECRET to enable email ingestion.
 49→    console.error("EMAIL_INGEST_WEBHOOK_SECRET not configured — rejecting request");
 50→    return false;
 51→  }
 52→
 53→  // Check signature header
 54→  const signature = req.headers.get("x-webhook-signature");
 55→
 56→  if (!signature) {
 57→    // Also allow secret as a query parameter (for simpler webhook providers)
 58→    const url = new URL(req.url);
 59→    const querySecret = url.searchParams.get("secret");
 60→    return querySecret === secret;
 61→  }
 62→
 63→  // Verify HMAC-SHA256 signature
 64→  try {
 65→    const key = await crypto.subtle.importKey(
 66→      "raw",
 67→      new TextEncoder().encode(secret),
 68→      { name: "HMAC", hash: "SHA-256" },
 69→      false,
 70→      ["verify"]
 71→    );
 72→
 73→    const signatureBytes = Uint8Array.from(
 74→      atob(signature),
 75→      (c: string) => c.charCodeAt(0)
 76→    );
 77→
 78→    return await crypto.subtle.verify("HMAC", key, signatureBytes, body);
 79→  } catch (e) {
 80→    console.error("Signature verification failed:", e);
 81→    return false;
 82→  }
 83→}
