 86→/**
 87→ * Verify Resend inbound webhook signature using Svix.
 88→ * Resend sends svix-id, svix-timestamp, svix-signature headers.
 89→ */
 90→function verifySvixSignature(req: Request, rawBody: string): boolean {
 91→  const secret = Deno.env.get("RESEND_INBOUND_WEBHOOK_SECRET");
 92→  if (!secret) return false;
 93→
 94→  const svixId = req.headers.get("svix-id");
 95→  const svixTimestamp = req.headers.get("svix-timestamp");
 96→  const svixSignature = req.headers.get("svix-signature");
 97→
 98→  if (!svixId || !svixTimestamp || !svixSignature) return false;
 99→
100→  try {
101→    const wh = new Webhook(secret);
102→    wh.verify(rawBody, {
103→      "svix-id": svixId,
104→      "svix-timestamp": svixTimestamp,
105→      "svix-signature": svixSignature,
106→    });
107→    return true;
108→  } catch (e) {
109→    console.error("Svix signature verification failed:", e);
110→    return false;
111→  }
112→}
