import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

async function authenticateAdmin(req: Request) {
  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY")!;

  const authHeader = req.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) throw new Error("No auth");

  const supabaseUser = createClient(SUPABASE_URL, anonKey, {
    global: { headers: { Authorization: authHeader } },
  });
  const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
  if (userError || !user) throw new Error("Unauthorized");
  const adminUserId = user.id;

  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  const { data: roles } = await supabase.from("user_roles").select("role").eq("user_id", adminUserId);
  if (!roles?.some((r: any) => r.role === "admin")) {
    throw new Error("Admin access required");
  }

  return { supabase, adminUserId };
}

serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });

  try {
    const { supabase, adminUserId } = await authenticateAdmin(req);

    let body: any = null;
    try {
      const text = await req.text();
      if (text) body = JSON.parse(text);
    } catch {
      // empty or invalid body — treat as list request
    }

    const action = body?.action;

    // ─── Ban / Suspend user ───
    if (action === "ban") {
      const { user_id, banned } = body;
      if (!user_id) throw new Error("user_id required");
      if (banned) {
        const { error } = await supabase.auth.admin.updateUserById(user_id, { ban_duration: "876000h" }); // ~100 years
        if (error) throw error;
      } else {
        const { error } = await supabase.auth.admin.updateUserById(user_id, { ban_duration: "none" });
        if (error) throw error;
      }
      return new Response(JSON.stringify({ success: true }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ─── Get user activity detail ───
    if (action === "activity") {
      const { user_id } = body;
      if (!user_id) throw new Error("user_id required");

      const [usageRes, jobsRes, resumesRes, paymentsRes] = await Promise.all([
        supabase.from("usage_logs").select("*").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
        supabase.from("jobs").select("id, title, status, created_at").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
        supabase.from("resumes").select("id, filename, status, created_at, job_id").order("created_at", { ascending: false }).limit(100),
        supabase.from("payments").select("id, amount, currency, status, credits_purchased, created_at").eq("user_id", user_id).order("created_at", { ascending: false }).limit(50),
      ]);

      // Filter resumes to only those belonging to user's jobs
      const jobIds = new Set(jobsRes.data?.map((j: any) => j.id) ?? []);
      const userResumes = resumesRes.data?.filter((r: any) => jobIds.has(r.job_id)) ?? [];

      return new Response(JSON.stringify({
        usage_logs: usageRes.data ?? [],
        jobs: jobsRes.data ?? [],
        resumes: userResumes,
        payments: paymentsRes.data ?? [],
      }), { headers: { ...corsHeaders, "Content-Type": "application/json" } });
    }

    // ─── GDPR data export ───
    if (action === "gdpr_export") {
      const { user_id } = body;
      if (!user_id) throw new Error("user_id required");

      const { data: authUser } = await supabase.auth.admin.getUserById(user_id);
      const [profileRes, usageRes, jobsRes, paymentsRes, rolesRes] = await Promise.all([
        supabase.from("profiles").select("*").eq("user_id", user_id),
        supabase.from("usage_logs").select("*").eq("user_id", user_id),
        supabase.from("jobs").select("*").eq("user_id", user_id),
        supabase.from("payments").select("*").eq("user_id", user_id),
        supabase.from("user_roles").select("*").eq("user_id", user_id),
      ]);

      // Get resumes for user's jobs
      const jobIds = jobsRes.data?.map((j: any) => j.id) ?? [];
      let resumes: any[] = [];
      if (jobIds.length > 0) {
        const { data } = await supabase.from("resumes").select("id, filename, status, created_at, candidate_name, source").in("job_id", jobIds);
        resumes = data ?? [];
      }

      const exportData = {
        exported_at: new Date().toISOString(),
        user: {
          id: authUser?.user?.id,
          email: authUser?.user?.email,
          created_at: authUser?.user?.created_at,
          last_sign_in_at: authUser?.user?.last_sign_in_at,
        },
        profile: profileRes.data?.[0] ?? null,
        roles: rolesRes.data ?? [],
        jobs: jobsRes.data ?? [],
        resumes,
        usage_logs: usageRes.data ?? [],
        payments: paymentsRes.data ?? [],
      };

      return new Response(JSON.stringify(exportData), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ─── Update user profile (existing) ───
    if (body && body.user_id && !action) {
      const { user_id, credits, plan, email_enabled, bonus_credits, subscription_credits, topup_credits } = body;
      const updates: any = {};
      if (credits !== undefined) updates.credits = credits;
      if (plan !== undefined) updates.plan = plan;
      if (email_enabled !== undefined) updates.email_enabled = email_enabled;
      if (bonus_credits !== undefined) updates.bonus_credits = Math.max(0, bonus_credits);
      if (subscription_credits !== undefined) updates.subscription_credits = Math.max(0, subscription_credits);
      if (topup_credits !== undefined) updates.topup_credits = Math.max(0, topup_credits);

      const { error } = await supabase.from("profiles").update(updates).eq("user_id", user_id);
      if (error) throw error;

      return new Response(JSON.stringify({ success: true }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ─── Regenerate user inbox email ───
    if (action === "regenerate_inbox") {
      const { user_id } = body;
      if (!user_id) throw new Error("user_id required");

      const { data, error } = await supabase.rpc("generate_user_inbox_email", { p_user_id: user_id });
      if (error) throw error;

      return new Response(JSON.stringify({ success: true, inbox_email: data }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ─── Update platform config (email settings etc.) ───
    if (action === "update_config") {
      const allowedFields = [
        "email_ingestion_enabled",
        "outbound_email_enabled",
        "resend_api_key",
        "email_from_address",
        "email_from_name",
        "email_notify_ranking_complete",
        "email_notify_resume_received",
        "max_file_size_mb",
        "max_resumes_per_job",
        "payg_per_resume_cost",
        "resume_retention_days",
        "inbound_email_domain",
        "resend_inbound_webhook_secret",
      ];

      const updates = body.updates || {};
      const setClauses: string[] = [];
      const values: any[] = [];
      let paramIdx = 1;

      for (const [key, val] of Object.entries(updates)) {
        if (allowedFields.includes(key)) {
          setClauses.push(`${key} = $${paramIdx}`);
          values.push(val);
          paramIdx++;
        }
      }

      if (setClauses.length === 0) throw new Error("No valid fields to update");

      setClauses.push(`updated_at = now()`);
      const sql = `UPDATE platform_config SET ${setClauses.join(", ")} WHERE id = (SELECT id FROM platform_config LIMIT 1)`;

      const { error } = await supabase.rpc("exec_sql", { query: sql, params: values }).maybeSingle();

      // Fallback: if exec_sql RPC doesn't exist, use direct update
      if (error) {
        // Try direct update via service role (bypasses PostgREST cache for service role)
        const { data: configRow } = await supabase.from("platform_config").select("id").limit(1).single();
        if (!configRow) throw new Error("No platform_config row found");

        const cleanUpdates: any = {};
        for (const [key, val] of Object.entries(updates)) {
          if (allowedFields.includes(key)) cleanUpdates[key] = val;
        }

        const { error: updateErr } = await supabase.from("platform_config").update(cleanUpdates).eq("id", configRow.id);
        if (updateErr) throw updateErr;
      }

      return new Response(JSON.stringify({ success: true }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ─── Get platform config ───
    if (action === "get_config") {
      const { data, error } = await supabase.from("platform_config").select("*").limit(1).single();
      if (error) throw error;
      // Mask the Resend API key for security
      if (data && (data as any).resend_api_key) {
        const key = (data as any).resend_api_key as string;
        (data as any).resend_api_key_masked = key.slice(0, 8) + "***" + key.slice(-4);
        (data as any).has_resend_key = true;
        delete (data as any).resend_api_key;
      } else {
        (data as any).has_resend_key = false;
      }
      return new Response(JSON.stringify(data), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ─── Get email templates ───
    if (action === "get_templates") {
      const { data, error } = await supabase
        .from("email_templates")
        .select("*")
        .order("template_key");
      if (error) throw error;
      return new Response(JSON.stringify(data), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ─── Update email template ───
    if (action === "update_template") {
      const { template_id, subject, body_html } = body;
      if (!template_id) throw new Error("template_id required");
      const { error } = await supabase
        .from("email_templates")
        .update({ subject, body_html, updated_at: new Date().toISOString() })
        .eq("id", template_id);
      if (error) throw error;
      return new Response(JSON.stringify({ success: true }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // ─── List all users (default) ───
    const { data: authUsers } = await supabase.auth.admin.listUsers({ perPage: 1000 });
    const { data: profiles } = await supabase.from("profiles").select("*");
    const { data: userRoles } = await supabase.from("user_roles").select("*");

    const users = authUsers?.users?.map((u: any) => {
      const profile = profiles?.find((p: any) => p.user_id === u.id);
      const role = userRoles?.find((r: any) => r.user_id === u.id);
      return {
        id: u.id,
        email: u.email,
        credits: profile?.credits ?? 0,
        subscription_credits: profile?.subscription_credits ?? 0,
        topup_credits: profile?.topup_credits ?? 0,
        bonus_credits: profile?.bonus_credits ?? 0,
        plan: profile?.plan ?? "free",
        role: role?.role ?? "user",
        inbox_email: profile?.inbox_email ?? null,
        email_enabled: profile?.email_enabled ?? true,
        created_at: u.created_at,
        last_sign_in_at: u.last_sign_in_at ?? null,
        banned_until: u.banned_until ?? null,
      };
    }) ?? [];

    return new Response(JSON.stringify(users), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err: unknown) {
    let msg = "Unknown error";
    if (err instanceof Error) msg = err.message;
    else if (typeof err === "object" && err !== null && "message" in err) msg = String((err as any).message);
    else msg = JSON.stringify(err);
    const status = msg === "Admin access required" ? 403 : 500;
    return new Response(JSON.stringify({ error: msg }), {
      status, headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

