import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { toast } from "sonner";
import {
  Copy, Mail, Globe, Link2, Info, Inbox, Send, Key,
  CheckCircle2, AlertCircle, Save, FileText, Search,
  Bell, Shield, Eye, EyeOff,
  Plug, Settings2, TestTube, Loader2,
  AlertTriangle, XCircle, RefreshCw
} from "lucide-react";
import { Table, TableHeader, TableBody, TableHead, TableRow, TableCell } from "@/components/ui/table";
import EmailIngestLogsCard from "./EmailIngestLogsCard";

const WEBHOOK_URL = "https://zkzontawprihrzpayeam.supabase.co/functions/v1/email-ingest";

async function adminCall(body: any) {
  const { data: { session } } = await supabase.auth.getSession();
  const res = await supabase.functions.invoke("admin-users", {
    headers: { Authorization: `Bearer ${session?.access_token}` },
    body,
  });
  if (res.error) throw new Error(res.error.message || "Admin call failed");
  const data = res.data as any;
  if (data?.error) throw new Error(data.error);
  return data;
}

// ─── Resend health state ───
interface ResendHealth {
  keyValid: boolean;
  domainVerified: boolean;
  domainName: string;
  fromEmail: string;
  totalDomains: number;
}

// ─── Toggle row component ───
function ToggleRow({
  icon: Icon, label, description, checked, onToggle, disabled = false
}: {
  icon: React.ElementType; label: string; description: string;
  checked: boolean; onToggle: (v: boolean) => void; disabled?: boolean;
}) {
  return (
    <div className="flex items-center justify-between rounded-xl border border-border p-4 hover:bg-muted/30 transition-colors">
      <div className="flex items-center gap-3">
        <div className="h-9 w-9 rounded-lg bg-primary/10 flex items-center justify-center shrink-0">
          <Icon className="h-4 w-4 text-primary" />
        </div>
        <div className="space-y-0.5">
          <Label className="text-sm font-medium cursor-pointer">{label}</Label>
          <p className="text-xs text-muted-foreground">{description}</p>
        </div>
      </div>
      <Switch checked={checked} onCheckedChange={onToggle} disabled={disabled} />
    </div>
  );
}

// ─── Health Alert Banner ───
function HealthBanner({ health, loading, onVerify }: {
  health: ResendHealth | null;
  loading: boolean;
  onVerify: () => void;
}) {
  if (loading) {
    return (
      <div className="rounded-lg border border-border bg-muted/30 p-4 flex items-center gap-3">
        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
        <span className="text-sm text-muted-foreground">Checking Resend connection...</span>
      </div>
    );
  }

  if (!health) return null;

  const issues: { icon: React.ElementType; text: string; severity: "error" | "warning" }[] = [];

  if (!health.keyValid) {
    issues.push({ icon: XCircle, text: "API key is invalid or not configured", severity: "error" });
  }
  if (health.keyValid && !health.domainVerified) {
    issues.push({
      icon: AlertTriangle,
      text: `Domain for "${health.fromEmail}" is not verified in Resend. Emails will fail.`,
      severity: "warning",
    });
  }

  if (issues.length === 0 && health.keyValid) {
    return (
      <div className="rounded-lg border border-green-200 bg-green-50 dark:border-green-900 dark:bg-green-950/50 p-4 space-y-2">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <CheckCircle2 className="h-4 w-4 text-green-600" />
            <span className="text-sm font-medium text-green-700 dark:text-green-400">
              Resend Connected{health.domainName ? ` — ${health.domainName}` : ""}
            </span>
          </div>
          <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
            <RefreshCw className="h-3 w-3" /> Recheck
          </Button>
        </div>
        <div className="flex gap-3 text-xs text-green-600 dark:text-green-500">
          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> API key valid</span>
          <span className="flex items-center gap-1"><CheckCircle2 className="h-3 w-3" /> Domain verified</span>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {issues.map((issue, i) => (
        <div
          key={i}
          className={`rounded-lg border p-3 flex items-start gap-2 ${
            issue.severity === "error"
              ? "border-destructive/50 bg-destructive/10 text-destructive"
              : "border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 text-amber-700 dark:text-amber-400"
          }`}
        >
          <issue.icon className="h-4 w-4 shrink-0 mt-0.5" />
          <p className="text-xs">{issue.text}</p>
        </div>
      ))}
      <div className="flex justify-end">
        <Button variant="ghost" size="sm" className="gap-1.5 h-7 text-xs" onClick={onVerify}>
          <RefreshCw className="h-3 w-3" /> Recheck
        </Button>
      </div>
    </div>
  );
}

const EmailSettingsTab = () => {
  const qc = useQueryClient();
  const [search, setSearch] = useState("");
  const [testEmailTo, setTestEmailTo] = useState("");
  const [sendingTest, setSendingTest] = useState(false);
  const [showKey, setShowKey] = useState(false);
  const [regeneratingUser, setRegeneratingUser] = useState<string | null>(null);
  const [dnsChecking, setDnsChecking] = useState(false);
  const [dnsResult, setDnsResult] = useState<{
    status: string;
    mx_records: { exchange: string; priority: number }[];
    points_to_expected: boolean;
  } | null>(null);

  const [resendApiKey, setResendApiKey] = useState("");
  const [fromAddress, setFromAddress] = useState("");
  const [fromName, setFromName] = useState("");
  const [inboundDomain, setInboundDomain] = useState("");
  const [inboundWebhookSecret, setInboundWebhookSecret] = useState("");
  const [showWebhookSecret, setShowWebhookSecret] = useState(false);
  const [configLoaded, setConfigLoaded] = useState(false);

  // Resend health state
  const [resendHealth, setResendHealth] = useState<ResendHealth | null>(null);
  const [healthLoading, setHealthLoading] = useState(false);

  const { data: config } = useQuery({
    queryKey: ["admin_config"],
    queryFn: () => adminCall({ action: "get_config" }),
  });

  useEffect(() => {
    if (config && !configLoaded) {
      setResendApiKey(config.resend_api_key_masked || "");
      setFromAddress(config.email_from_address || "noreply@rankora.co");
      setFromName(config.email_from_name || "Rankora");
      setInboundDomain(config.inbound_email_domain || "inbound.rankora.co");
      setInboundWebhookSecret(config.resend_inbound_webhook_secret_masked || "");
      setConfigLoaded(true);
    }
  }, [config, configLoaded]);

  // Auto-check health when config loads and key exists
  useEffect(() => {
    if (config?.has_resend_key && !resendHealth && !healthLoading) {
      verifyResendConnection();
    }
  }, [config?.has_resend_key]);

  const { data: templates = [] } = useQuery({
    queryKey: ["email_templates"],
    queryFn: () => adminCall({ action: "get_templates" }),
  });

  const { data: users = [] } = useQuery({
    queryKey: ["admin_users_email"],
    queryFn: async () => {
      const { data: { session } } = await supabase.auth.getSession();
      const res = await supabase.functions.invoke("admin-users", {
        headers: { Authorization: `Bearer ${session?.access_token}` },
      });
      if (res.error) throw res.error;
      return res.data as Array<{
        id: string; email: string; inbox_email: string | null;
        email_enabled: boolean; credits: number; plan: string;
      }>;
    },
  });

  // ─── Verify Resend Connection ───
  const verifyResendConnection = async () => {
    setHealthLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke("admin-test-integration", {
        body: { key_name: "RESEND_API_KEY" },
      });
      if (error) throw error;

      const d = data.details || {};
      setResendHealth({
        keyValid: d.keyValid ?? false,
        domainVerified: d.domainVerified ?? false,
        domainName: d.domainName || "",
        fromEmail: d.fromEmail || "",
        totalDomains: d.totalDomains || 0,
      });

      // Also refresh the integrations query
      qc.invalidateQueries({ queryKey: ["admin_integrations"] });
    } catch (e: any) {
      toast.error("Failed to verify connection: " + e.message);
      setResendHealth({
        keyValid: false,
        domainVerified: false,
        domainName: "",
        fromEmail: "",
        totalDomains: 0,
      });
    } finally {
      setHealthLoading(false);
    }
  };

  // ─── Mutations ───
  const updateConfig = useMutation({
    mutationFn: (updates: Record<string, any>) => adminCall({ action: "update_config", updates }),
    onSuccess: () => qc.invalidateQueries({ queryKey: ["admin_config"] }),
    onError: (e: any) => toast.error(e.message),
  });

  const toggleOutbound = useMutation({
    mutationFn: (enabled: boolean) => adminCall({ action: "update_config", updates: { outbound_email_enabled: enabled } }),
    onSuccess: () => { toast.success("Outbound email updated"); qc.invalidateQueries({ queryKey: ["admin_config"] }); },
    onError: (e: any) => toast.error(e.message),
  });

  const toggleGlobal = useMutation({
    mutationFn: (enabled: boolean) => adminCall({ action: "update_config", updates: { email_ingestion_enabled: enabled } }),
    onSuccess: () => { toast.success("Email ingestion updated"); qc.invalidateQueries({ queryKey: ["admin_config"] }); },
    onError: (e: any) => toast.error(e.message),
  });

  const toggleNotification = useMutation({
    mutationFn: ({ field, enabled }: { field: string; enabled: boolean }) =>
      adminCall({ action: "update_config", updates: { [field]: enabled } }),
    onSuccess: () => { toast.success("Notification updated"); qc.invalidateQueries({ queryKey: ["admin_config"] }); },
    onError: (e: any) => toast.error(e.message),
  });

  const saveResendConfig = useMutation({
    mutationFn: async () => {
      const updates: Record<string, any> = {
        email_from_address: fromAddress,
        email_from_name: fromName,
      };
      if (resendApiKey && !resendApiKey.includes("***")) {
        updates.resend_api_key = resendApiKey;
      }
      return adminCall({ action: "update_config", updates });
    },
    onSuccess: () => {
      toast.success("Resend settings saved!");
      qc.invalidateQueries({ queryKey: ["admin_config"] });
      // Re-verify connection after saving
      setTimeout(() => verifyResendConnection(), 500);
    },
    onError: (e: any) => toast.error(e.message),
  });

  const updateTemplate = useMutation({
    mutationFn: ({ id, subject, body_html }: { id: string; subject: string; body_html: string }) =>
      adminCall({ action: "update_template", template_id: id, subject, body_html }),
    onSuccess: () => { toast.success("Template saved"); qc.invalidateQueries({ queryKey: ["email_templates"] }); },
    onError: (e: any) => toast.error(e.message),
  });

  const toggleUser = useMutation({
    mutationFn: async ({ userId, enabled }: { userId: string; enabled: boolean }) => {
      const { data: { session } } = await supabase.auth.getSession();
      const res = await supabase.functions.invoke("admin-users", {
        method: "POST",
        headers: { Authorization: `Bearer ${session?.access_token}` },
        body: { user_id: userId, email_enabled: enabled },
      });
      if (res.error) throw res.error;
    },
    onSuccess: () => { toast.success("User email updated"); qc.invalidateQueries({ queryKey: ["admin_users_email"] }); },
    onError: (e: any) => toast.error(e.message),
  });

  const handleSendTestEmail = async () => {
    if (!testEmailTo) { toast.error("Enter a recipient email"); return; }
    setSendingTest(true);
    try {
      const res = await supabase.functions.invoke("send-email", {
        body: {
          to: testEmailTo,
          template_key: "ranking_complete",
          variables: { user_name: "Admin", job_title: "Test Job", resume_count: "5", job_id: "test", app_url: window.location.origin },
        },
      });
      if (res.error) throw new Error(res.error.message);
      const data = res.data as any;
      if (data?.error) {
        toast.error(data.error);
      } else if (data?.skipped) {
        toast.error("Email skipped — check outbound is enabled");
      } else {
        toast.success(`Test email sent to ${testEmailTo}`);
      }
    } catch (e: any) { toast.error(e.message); }
    finally { setSendingTest(false); }
  };

  const copyToClipboard = (text: string) => { navigator.clipboard.writeText(text); toast.success("Copied!"); };

  const filtered = users.filter(
    (u) => u.email?.toLowerCase().includes(search.toLowerCase()) || u.inbox_email?.toLowerCase().includes(search.toLowerCase())
  );

  const globalEnabled = config?.email_ingestion_enabled ?? true;
  const outboundEnabled = config?.outbound_email_enabled ?? false;
  const notifyRankingComplete = config?.email_notify_ranking_complete ?? true;
  const notifyResumeReceived = config?.email_notify_resume_received ?? true;
  const hasApiKey = !!config?.has_resend_key;
  const maskedKey = hasApiKey && !resendApiKey ? "***hidden***" : resendApiKey;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-semibold">Email Settings</h2>
          <p className="text-sm text-muted-foreground">Manage email sending, receiving, and templates</p>
        </div>
        <Badge variant={hasApiKey && outboundEnabled ? "default" : "secondary"} className={`gap-1.5 px-3 py-1 ${hasApiKey && outboundEnabled ? "bg-green-600 hover:bg-green-700" : ""}`}>
          {hasApiKey && outboundEnabled ? <><CheckCircle2 className="h-3 w-3" /> Connected</> : <><AlertCircle className="h-3 w-3" /> Not Connected</>}
        </Badge>
      </div>

      <Tabs defaultValue="connect" className="w-full">
        <TabsList className="grid w-full grid-cols-4 h-11">
          <TabsTrigger value="connect" className="gap-1.5"><Plug className="h-3.5 w-3.5" /> Connect</TabsTrigger>
          <TabsTrigger value="notifications" className="gap-1.5"><Bell className="h-3.5 w-3.5" /> Notifications</TabsTrigger>
          <TabsTrigger value="templates" className="gap-1.5"><FileText className="h-3.5 w-3.5" /> Templates</TabsTrigger>
          <TabsTrigger value="inbound" className="gap-1.5"><Inbox className="h-3.5 w-3.5" /> Inbound</TabsTrigger>
        </TabsList>

        {/* ─── Connect Tab ─── */}
        <TabsContent value="connect" className="space-y-5 mt-5">
          {/* Health Banner — shows at top when key exists */}
          {hasApiKey && (
            <HealthBanner health={resendHealth} loading={healthLoading} onVerify={verifyResendConnection} />
          )}

          {/* Email Provider */}
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Key className="h-4 w-4" /> Email Provider
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label className="text-sm font-medium">API Key</Label>
                <div className="flex gap-2">
                  <div className="relative flex-1">
                    <Input
                      type={showKey ? "text" : "password"}
                      placeholder="re_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"
                      value={configLoaded ? maskedKey : ""}
                      onChange={(e) => setResendApiKey(e.target.value)}
                      className="font-mono text-sm pr-10"
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      className="absolute right-1 top-1/2 -translate-y-1/2 h-7 w-7"
                      onClick={() => setShowKey(!showKey)}
                    >
                      {showKey ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}
                    </Button>
                  </div>
                </div>
                <p className="text-xs text-muted-foreground">Your Resend API key</p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label className="text-sm font-medium">From Email</Label>
                  <Input
                    type="email"
                    placeholder="noreply@yourdomain.com"
                    value={fromAddress}
                    onChange={(e) => setFromAddress(e.target.value)}
                  />
                  <p className="text-xs text-muted-foreground">Ensure this domain is verified in your Resend account</p>
                </div>
                <div className="space-y-2">
                  <Label className="text-sm font-medium">From Name</Label>
                  <Input
                    placeholder="Rankora"
                    value={fromName}
                    onChange={(e) => setFromName(e.target.value)}
                  />
                </div>
              </div>

              <div className="flex gap-2">
                <Button onClick={() => saveResendConfig.mutate()} disabled={saveResendConfig.isPending} className="gap-2">
                  <Save className="h-4 w-4" />
                  {saveResendConfig.isPending ? "Saving..." : "Save"}
                </Button>
                {hasApiKey && (
                  <Button
                    variant="outline"
                    onClick={verifyResendConnection}
                    disabled={healthLoading}
                    className="gap-2"
                  >
                    {healthLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
                    Verify Connection
                  </Button>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Master Toggle + Test */}
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Settings2 className="h-4 w-4" /> Email Sending
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <ToggleRow
                icon={Send}
                label="Enable Outbound Emails"
                description="Send transactional emails to users"
                checked={outboundEnabled}
                onToggle={(v) => toggleOutbound.mutate(v)}
              />

              {/* Domain not verified warning */}
              {hasApiKey && outboundEnabled && resendHealth && !resendHealth.domainVerified && resendHealth.keyValid && (
                <div className="rounded-lg border border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 p-3 flex items-start gap-2">
                  <AlertTriangle className="h-4 w-4 text-amber-600 shrink-0 mt-0.5" />
                  <div className="space-y-1">
                    <p className="text-xs font-medium text-amber-700 dark:text-amber-400">
                      Domain Not Verified
                    </p>
                    <p className="text-xs text-amber-600 dark:text-amber-500">
                      The domain for <strong>{fromAddress}</strong> is not verified in Resend. Emails will fail until the domain is added and DNS records are configured.{" "}
                      <a href="https://resend.com/domains" target="_blank" rel="noopener noreferrer" className="underline font-medium">
                        Verify in Resend
                      </a>
                    </p>
                  </div>
                </div>
              )}

              {/* Test Email — only show when connected */}
              {hasApiKey && outboundEnabled && (
                <div className="rounded-xl border border-dashed border-green-300 dark:border-green-800 bg-green-50/50 dark:bg-green-950/30 p-4 space-y-3">
                  <div className="flex items-center gap-2">
                    <TestTube className="h-4 w-4 text-green-600" />
                    <span className="text-sm font-medium text-green-700 dark:text-green-400">Send a Test Email</span>
                  </div>
                  <div className="flex gap-2">
                    <Input
                      type="email"
                      placeholder="your@email.com"
                      value={testEmailTo}
                      onChange={(e) => setTestEmailTo(e.target.value)}
                      className="flex-1"
                    />
                    <Button onClick={handleSendTestEmail} disabled={sendingTest} variant="outline" className="gap-1.5 shrink-0 border-green-300 dark:border-green-800 hover:bg-green-100 dark:hover:bg-green-900">
                      <Send className="h-3.5 w-3.5" />
                      {sendingTest ? "Sending..." : "Send Test"}
                    </Button>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* ─── Notifications Tab ─── */}
        <TabsContent value="notifications" className="space-y-5 mt-5">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Bell className="h-4 w-4" /> Email Notifications
              </CardTitle>
              <CardDescription>Control which emails are sent to users</CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              {!outboundEnabled && (
                <div className="rounded-lg border border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950 p-3 flex items-center gap-2 mb-2">
                  <AlertCircle className="h-4 w-4 text-amber-600 shrink-0" />
                  <p className="text-xs text-amber-700 dark:text-amber-400">
                    Outbound email is disabled. Enable it in the <strong>Connect</strong> tab first.
                  </p>
                </div>
              )}

              <ToggleRow
                icon={CheckCircle2}
                label="Ranking Complete"
                description="Email users when their resume ranking is complete"
                checked={notifyRankingComplete}
                onToggle={(v) => toggleNotification.mutate({ field: "email_notify_ranking_complete", enabled: v })}
                disabled={!outboundEnabled}
              />
              <ToggleRow
                icon={Mail}
                label="Resume Received"
                description="Email users when resumes are received via inbox"
                checked={notifyResumeReceived}
                onToggle={(v) => toggleNotification.mutate({ field: "email_notify_resume_received", enabled: v })}
                disabled={!outboundEnabled}
              />
            </CardContent>
          </Card>
        </TabsContent>

        {/* ─── Templates Tab ─── */}
        <TabsContent value="templates" className="space-y-5 mt-5">
          {templates.length === 0 ? (
            <Card>
              <CardContent className="py-12 text-center space-y-2">
                <FileText className="h-10 w-10 mx-auto text-muted-foreground/50" />
                <p className="text-sm text-muted-foreground">No email templates found</p>
                <p className="text-xs text-muted-foreground">No templates configured yet.</p>
              </CardContent>
            </Card>
          ) : (
            templates.map((tpl: any) => (
              <TemplateEditor
                key={tpl.id}
                template={tpl}
                onSave={(subject, body_html) => updateTemplate.mutate({ id: tpl.id, subject, body_html })}
                saving={updateTemplate.isPending}
              />
            ))
          )}
        </TabsContent>

        {/* ─── Inbound Tab ─── */}
        <TabsContent value="inbound" className="space-y-5 mt-5">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Inbox className="h-4 w-4" /> Inbound Email Ingestion
              </CardTitle>
              <CardDescription>Receive resumes via email and auto-add them to jobs</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <ToggleRow
                icon={Shield}
                label="Global Email Ingestion"
                description="Enable or disable email ingestion for all users"
                checked={globalEnabled}
                onToggle={(v) => toggleGlobal.mutate(v)}
              />

              {/* Configurable inbound domain */}
              <div className="space-y-2">
                <Label className="text-sm font-medium">Inbound Domain</Label>
                <div className="flex gap-2">
                  <Input
                    placeholder="inbound.rankora.co"
                    value={inboundDomain}
                    onChange={(e) => setInboundDomain(e.target.value)}
                    className="flex-1"
                  />
                  <Button
                    variant="outline"
                    onClick={() => {
                      updateConfig.mutate({ inbound_email_domain: inboundDomain });
                      toast.success("Inbound domain saved");
                    }}
                    disabled={updateConfig.isPending}
                    className="gap-1.5"
                  >
                    <Save className="h-3.5 w-3.5" /> Save
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground">
                  All user and job inbox emails use this domain. Changing it will apply to newly generated addresses.
                </p>
              </div>

              {/* Webhook Signing Secret */}
              <div className="space-y-2">
                <Label className="text-sm font-medium">Resend Webhook Secret</Label>
                <div className="flex gap-2">
                  <div className="relative flex-1">
                    <Input
                      type={showWebhookSecret ? "text" : "password"}
                      placeholder="whsec_..."
                      value={inboundWebhookSecret}
                      onChange={(e) => setInboundWebhookSecret(e.target.value)}
                    />
                    <Button
                      variant="ghost" size="icon"
                      className="absolute right-1 top-1/2 -translate-y-1/2 h-7 w-7"
                      onClick={() => setShowWebhookSecret(!showWebhookSecret)}
                    >
                      {showWebhookSecret ? <EyeOff className="h-3.5 w-3.5" /> : <Eye className="h-3.5 w-3.5" />}
                    </Button>
                  </div>
                  <Button
                    variant="outline"
                    onClick={() => {
                      if (!inboundWebhookSecret || inboundWebhookSecret.includes("***")) {
                        toast.error("Enter a new secret to save");
                        return;
                      }
                      updateConfig.mutate({ resend_inbound_webhook_secret: inboundWebhookSecret });
                      toast.success("Webhook secret saved");
                    }}
                    disabled={updateConfig.isPending}
                    className="gap-1.5"
                  >
                    <Save className="h-3.5 w-3.5" /> Save
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground">
                  Signing secret from your Resend webhook endpoint. Required to verify inbound emails.
                  {config?.has_inbound_webhook_secret && (
                    <span className="ml-1 text-green-600 font-medium">Configured</span>
                  )}
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                <CopyableField icon={Globe} label="Inbound Domain" value={`@${inboundDomain || "inbound.rankora.co"}`} onCopy={copyToClipboard} />
                <CopyableField icon={Link2} label="Webhook URL" value={WEBHOOK_URL} onCopy={copyToClipboard} small />
              </div>

              <div className="rounded-xl border border-border bg-muted/30 p-4 space-y-3">
                <div className="flex items-center gap-2 text-sm font-medium">
                  <Info className="h-4 w-4 text-muted-foreground" /> Inbound Email Setup
                </div>
                <div className="grid gap-2">
                  {[
                    { step: "1", text: `Add ${inboundDomain || "inbound.rankora.co"} as a receiving domain in the Resend dashboard` },
                    { step: "2", text: "Copy the MX record from Resend and add it to your DNS provider" },
                    { step: "3", text: "Paste the Webhook URL above as the endpoint, subscribe to email.received event" },
                    { step: "4", text: "Paste the webhook signing secret from your Resend endpoint above" },
                  ].map(({ step, text }) => (
                    <div key={step} className="flex items-start gap-2.5">
                      <span className="h-5 w-5 rounded-full bg-primary/10 text-primary text-xs font-bold flex items-center justify-center shrink-0 mt-0.5">
                        {step}
                      </span>
                      <span className="text-xs text-muted-foreground">{text}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* DNS Health Check */}
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    className="gap-1.5"
                    disabled={dnsChecking}
                    onClick={async () => {
                      setDnsChecking(true);
                      try {
                        const { data, error } = await supabase.functions.invoke("admin-test-integration", {
                          body: { key_name: "DNS_MX_CHECK", domain: inboundDomain || "inbound.rankora.co" },
                        });
                        if (error) throw error;
                        setDnsResult(data as any);
                      } catch (e: any) {
                        toast.error("DNS check failed: " + e.message);
                      } finally {
                        setDnsChecking(false);
                      }
                    }}
                  >
                    {dnsChecking ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Shield className="h-3.5 w-3.5" />}
                    Check MX Records
                  </Button>
                </div>

                {dnsResult && (
                  <div className={`rounded-lg border p-3 space-y-2 ${
                    dnsResult.points_to_expected
                      ? "border-green-200 bg-green-50 dark:border-green-900 dark:bg-green-950/50"
                      : dnsResult.mx_records?.length > 0
                        ? "border-amber-200 bg-amber-50 dark:border-amber-900 dark:bg-amber-950"
                        : "border-destructive/50 bg-destructive/10"
                  }`}>
                    <div className="flex items-center gap-2">
                      {dnsResult.points_to_expected ? (
                        <>
                          <CheckCircle2 className="h-4 w-4 text-green-600" />
                          <span className="text-sm font-medium text-green-700 dark:text-green-400">MX records configured correctly</span>
                        </>
                      ) : dnsResult.mx_records?.length > 0 ? (
                        <>
                          <AlertTriangle className="h-4 w-4 text-amber-600" />
                          <span className="text-sm font-medium text-amber-700 dark:text-amber-400">MX records found — verify they point to the correct provider</span>
                        </>
                      ) : (
                        <>
                          <XCircle className="h-4 w-4 text-destructive" />
                          <span className="text-sm font-medium text-destructive">No MX records found for {inboundDomain}</span>
                        </>
                      )}
                    </div>
                    {dnsResult.mx_records?.length > 0 && (
                      <div className="space-y-1">
                        {dnsResult.mx_records.map((mx, i) => (
                          <div key={i} className="text-xs text-muted-foreground font-mono">
                            Priority {mx.priority}: {mx.exchange}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                )}
              </div>
            </CardContent>
          </Card>

          {/* User Inbox Directory */}
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Inbox className="h-4 w-4" /> User Inboxes
              </CardTitle>
              <CardDescription>Manage per-user inbound email addresses</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="relative max-w-sm">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input placeholder="Search users..." value={search} onChange={(e) => setSearch(e.target.value)} className="pl-9" />
              </div>

              <div className="rounded-md border">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>User</TableHead>
                      <TableHead>Inbox</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="w-[120px]">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filtered.length === 0 ? (
                      <TableRow>
                        <TableCell colSpan={4} className="text-center text-muted-foreground py-8">No users found</TableCell>
                      </TableRow>
                    ) : (
                      filtered.map((u) => (
                        <TableRow key={u.id}>
                          <TableCell className="font-medium text-sm">{u.email}</TableCell>
                          <TableCell>
                            <div className="flex items-center gap-1.5">
                              <code className="text-xs bg-muted px-1.5 py-0.5 rounded truncate max-w-[220px]">{u.inbox_email || "—"}</code>
                              {u.inbox_email && (
                                <Button size="icon" variant="ghost" className="h-6 w-6" onClick={() => copyToClipboard(u.inbox_email!)}>
                                  <Copy className="h-3 w-3" />
                                </Button>
                              )}
                            </div>
                          </TableCell>
                          <TableCell>
                            <Badge variant={u.email_enabled ? "default" : "secondary"} className="text-xs">
                              {u.email_enabled ? "Active" : "Off"}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            <div className="flex items-center gap-1">
                              <Switch checked={u.email_enabled} onCheckedChange={(v) => toggleUser.mutate({ userId: u.id, enabled: v })} disabled={!globalEnabled} />
                              <Button
                                size="icon"
                                variant="ghost"
                                className="h-7 w-7"
                                title="Regenerate inbox email"
                                disabled={regeneratingUser === u.id}
                                onClick={async () => {
                                  setRegeneratingUser(u.id);
                                  try {
                                    await adminCall({ action: "regenerate_inbox", user_id: u.id });
                                    toast.success("Inbox regenerated");
                                    qc.invalidateQueries({ queryKey: ["admin_users_email"] });
                                  } catch (e: any) {
                                    toast.error(e.message);
                                  } finally {
                                    setRegeneratingUser(null);
                                  }
                                }}
                              >
                                {regeneratingUser === u.id ? (
                                  <Loader2 className="h-3 w-3 animate-spin" />
                                ) : (
                                  <RefreshCw className="h-3 w-3" />
                                )}
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </div>
            </CardContent>
          </Card>

          {/* Logs */}
          <EmailIngestLogsCard />
        </TabsContent>
      </Tabs>
    </div>
  );
};

// ─── Copyable field widget ───
function CopyableField({ icon: Icon, label, value, onCopy, small = false }: {
  icon: React.ElementType; label: string; value: string; onCopy: (v: string) => void; small?: boolean;
}) {
  return (
    <div className="rounded-xl border border-border p-3 space-y-1.5">
      <div className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground">
        <Icon className="h-3.5 w-3.5" /> {label}
      </div>
      <div className="flex items-center gap-2">
        <code className={`bg-muted px-2 py-1 rounded flex-1 ${small ? "text-[11px] truncate" : "text-sm"}`}>{value}</code>
        <Button size="icon" variant="ghost" className="h-7 w-7 shrink-0" onClick={() => onCopy(value)}>
          <Copy className="h-3 w-3" />
        </Button>
      </div>
    </div>
  );
}

// ─── Template editor with preview ───
function TemplateEditor({
  template, onSave, saving
}: {
  template: { id: string; template_key: string; subject: string; body_html: string; description: string | null };
  onSave: (subject: string, body_html: string) => void;
  saving: boolean;
}) {
  const [subject, setSubject] = useState(template.subject);
  const [bodyHtml, setBodyHtml] = useState(template.body_html);
  const [showPreview, setShowPreview] = useState(false);
  const dirty = subject !== template.subject || bodyHtml !== template.body_html;

  const variableHints: Record<string, string[]> = {
    ranking_complete: ["user_name", "job_title", "resume_count", "job_id", "app_url"],
    resume_received: ["user_name", "job_title", "attachment_count", "filename", "job_id", "app_url"],
  };
  const vars = variableHints[template.template_key] || [];

  const prettyName = template.template_key.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase());

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base flex items-center gap-2">
            <FileText className="h-4 w-4" /> {prettyName}
          </CardTitle>
          <Button variant="ghost" size="sm" className="gap-1.5 text-xs" onClick={() => setShowPreview(!showPreview)}>
            <Eye className="h-3 w-3" /> {showPreview ? "Edit" : "Preview"}
          </Button>
        </div>
        {template.description && <CardDescription>{template.description}</CardDescription>}
      </CardHeader>
      <CardContent className="space-y-4">
        {vars.length > 0 && (
          <div className="flex flex-wrap gap-1.5">
            <span className="text-xs text-muted-foreground">Variables:</span>
            {vars.map((v) => (
              <Badge key={v} variant="outline" className="text-[11px] font-mono px-1.5 py-0">{`{{${v}}}`}</Badge>
            ))}
          </div>
        )}

        {showPreview ? (
          <div className="rounded-lg border bg-white dark:bg-background p-4">
            <p className="text-xs text-muted-foreground mb-2">Subject: <strong>{subject}</strong></p>
            <div className="border rounded p-3 text-sm" dangerouslySetInnerHTML={{ __html: bodyHtml }} />
          </div>
        ) : (
          <>
            <div className="space-y-2">
              <Label className="text-sm font-medium">Subject Line</Label>
              <Input value={subject} onChange={(e) => setSubject(e.target.value)} />
            </div>
            <div className="space-y-2">
              <Label className="text-sm font-medium">Email Body (HTML)</Label>
              <Textarea value={bodyHtml} onChange={(e) => setBodyHtml(e.target.value)} className="font-mono text-xs min-h-[180px]" />
            </div>
          </>
        )}

        <Button onClick={() => onSave(subject, bodyHtml)} disabled={!dirty || saving} className="gap-2">
          <Save className="h-4 w-4" />
          {saving ? "Saving..." : "Save Template"}
        </Button>
      </CardContent>
    </Card>
  );
}

export default EmailSettingsTab;

