import { useState } from "react";
import { useAuth } from "@/hooks/useAuth";
import { useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger } from
"@/components/ui/dropdown-menu";
import { Badge } from "@/components/ui/badge";
import { Zap, LogOut, Settings, User, ShieldCheck, AlertTriangle, Coins, CalendarCheck, Lightbulb } from "lucide-react";
import { Link } from "react-router-dom";
import AuthDialog from "@/components/AuthDialog";

const AppHeader = () => {
  const { user, profile, isAdmin, signOut } = useAuth();
  const [authOpen, setAuthOpen] = useState(false);
  const [authTab, setAuthTab] = useState<"signin" | "signup">("signin");
  const navigate = useNavigate();

  const openAuth = (tab: "signin" | "signup") => {
    setAuthTab(tab);
    setAuthOpen(true);
  };

  return (
    <>
      <header className="border-b border-border bg-card">
        <div className="mx-auto max-w-[1200px] px-4 sm:px-6 flex items-center justify-between h-14">
          <Link to="/" className="flex items-center gap-2">
            <Zap className="h-5 w-5 text-primary" />
            <span className="font-semibold text-foreground tracking-tight">​Rankora    







    </span>
          </Link>
          <div className="flex items-center gap-3">
            {user ? <>
                {(() => {
                  const subCredits = profile?.subscription_credits ?? 0;
                  const topCredits = profile?.topup_credits ?? 0;
                  const bonusCredits = profile?.bonus_credits ?? 0;
                  const splitTotal = subCredits + topCredits + bonusCredits;
                  const legacyCredits = profile?.credits ?? 0;
                  const total = splitTotal > 0 ? splitTotal : legacyCredits;
                  const isLow = total < 3;
                  return isLow ? (
                    <Badge variant="destructive" className="gap-1.5 py-1 px-3 animate-pulse cursor-pointer" onClick={() => navigate("/settings")}>
                      <AlertTriangle className="h-3.5 w-3.5" />
                      {total} credits left
                    </Badge>
                  ) : (
                    <Badge variant="secondary" className="gap-1.5 py-1 px-3 cursor-pointer" onClick={() => navigate("/settings")}>
                      <Coins className="h-3.5 w-3.5" />
                      {total} credits
                    </Badge>
                  );
                })()}
                <div className="hidden sm:flex items-center gap-1">
                  <Button variant="ghost" size="sm" className="text-xs text-muted-foreground hover:text-foreground gap-1.5 h-8" asChild>
                    <Link to="/book-demo">
                      <CalendarCheck className="h-3.5 w-3.5" />
                      Book Demo
                    </Link>
                  </Button>
                  <Button variant="ghost" size="sm" className="text-xs text-muted-foreground hover:text-foreground gap-1.5 h-8" asChild>
                    <Link to="/request-feature">
                      <Lightbulb className="h-3.5 w-3.5" />
                      Request Feature
                    </Link>
                  </Button>
                </div>
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <Button variant="ghost" size="icon" className="rounded-full">
                      <User className="h-4 w-4" />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-48">
                    <DropdownMenuItem onClick={() => navigate("/settings")}>
                      <Settings className="h-4 w-4 mr-2" />
                      Settings
                    </DropdownMenuItem>
                    {isAdmin &&
                  <DropdownMenuItem onClick={() => navigate("/admin")}>
                        <ShieldCheck className="h-4 w-4 mr-2" />
                        Admin
                      </DropdownMenuItem>
                  }
                    <DropdownMenuSeparator className="sm:hidden" />
                    <DropdownMenuItem className="sm:hidden" onClick={() => navigate("/book-demo")}>
                      <CalendarCheck className="h-4 w-4 mr-2" />
                      Book Demo
                    </DropdownMenuItem>
                    <DropdownMenuItem className="sm:hidden" onClick={() => navigate("/request-feature")}>
                      <Lightbulb className="h-4 w-4 mr-2" />
                      Request Feature
                    </DropdownMenuItem>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem onClick={signOut}>
                      <LogOut className="h-4 w-4 mr-2" />
                      Sign out
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </> :

            <>
                <Button variant="ghost" size="sm" onClick={() => openAuth("signin")}>
                  Sign in
                </Button>
                <Button size="sm" onClick={() => openAuth("signup")}>
                  Sign up free
                </Button>
              </>
            }
          </div>
        </div>
      </header>
      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab={authTab} />
    </>);

};

export default AppHeader;

