                      <TableRow>
                        <TableHead className="w-10">
                          <Checkbox
                            checked={visibleResults.length > 0 && visibleResults.every(r => selectedResumes.has(r.resume_id))}
                            onCheckedChange={(checked) => {
                              if (checked) setSelectedResumes(prev => new Set([...prev, ...visibleResults.map(r => r.resume_id)]));
                              else setSelectedResumes(prev => { const next = new Set(prev); visibleResults.forEach(r => next.delete(r.resume_id)); return next; });
                            }}
                          />
                        </TableHead>
                        <TableHead className="w-14 text-center">#</TableHead>
                        <TableHead>Candidate</TableHead>
                        <TableHead className="w-32">Match</TableHead>
                        <TableHead className="w-20">Strength</TableHead>
                        <TableHead className="w-36"></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {visibleResults.map((r, index) => (
