          email_notify_resume_received: form.email_notify_resume_received,
          inbound_email_domain: form.inbound_email_domain,
        } as any)
        .eq("id", config?.id);
      if (error) throw error;
      toast.success("Resend settings saved");
      logAuditAction("integration.update", "platform_config", config?.id, { integration: "resend" });
      onConfigSaved?.();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
