import { useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { toast } from "sonner";
import { Plus, Pencil, Save, Trash2, Loader2, CheckCircle, AlertTriangle, Archive, RotateCcw, RefreshCw, Link2, ExternalLink } from "lucide-react";
import ConfirmDialog from "./ConfirmDialog";
import { logAuditAction } from "@/lib/auditLog";

const parseFunctionError = (error: any) => {
  const message = error?.message || "";
  const jsonStart = message.indexOf("{");
  if (jsonStart === -1) return null;
  try {
    return JSON.parse(message.slice(jsonStart));
  } catch {
    return null;
  }
};

const syncDodoProduct = async (action: string, payload: any) => {
  const { data, error } = await supabase.functions.invoke("manage-dodo-product", {
    body: { action, type: "plan", ...payload },
  });
  if (error) {
    const parsed = parseFunctionError(error);
    if (parsed?.not_found) return parsed;
    throw error;
  }
  if (data?.not_found) return data;
  if (data?.error) throw new Error(data.error);
  return data;
};

const PlansTab = () => {
  const qc = useQueryClient();
  const [saving, setSaving] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{ id: string; name: string; dodo_product_id?: string; dodo_credit_entitlement_id?: string; paymentCount?: number } | null>(null);
  const [showArchived, setShowArchived] = useState(false);
  const [verifying, setVerifying] = useState<string | null>(null);
  const [verifyResults, setVerifyResults] = useState<Record<string, { exists: boolean; is_active?: boolean; dodo_name?: string }>>({});

  const { data: plans } = useQuery({
    queryKey: ["admin_plans"],
    queryFn: async () => {
      const { data, error } = await supabase.from("plans").select("*").order("created_at");
      if (error) throw error;
      return data;
    },
  });

  // Get payment counts for archived plans (for delete eligibility)
  const { data: paymentCounts } = useQuery({
    queryKey: ["admin_plan_payment_counts"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("payments")
        .select("plan_id")
        .not("plan_id", "is", null);
      if (error) throw error;
      const counts: Record<string, number> = {};
      data?.forEach((p: any) => { counts[p.plan_id] = (counts[p.plan_id] || 0) + 1; });
      return counts;
    },
  });

  const activePlans = plans?.filter((p: any) => p.active) ?? [];
  const archivedPlans = plans?.filter((p: any) => !p.active) ?? [];

  const [editPlan, setEditPlan] = useState<any>(null);
  const [form, setForm] = useState({ name: "", price: "", credits: "", billing_type: "monthly", active: true, per_resume_cost: "0.05", description: "" });

  const openNew = () => {
    setForm({ name: "", price: "", credits: "", billing_type: "monthly", active: true, per_resume_cost: "0.05", description: "" });
    setEditPlan("new");
  };

  const openEdit = (p: any) => {
    setForm({ name: p.name, price: String(p.price), credits: String(p.credits), billing_type: p.billing_type, active: p.active, per_resume_cost: String(p.per_resume_cost ?? 0.05), description: p.description || "" });
    setEditPlan(p);
  };

  const validate = () => {
    if (!form.name.trim()) { toast.error("Plan name is required"); return false; }
    if (!form.price || parseFloat(form.price) <= 0) { toast.error("Price must be greater than 0"); return false; }
    if (!form.credits || parseInt(form.credits) <= 0) { toast.error("Credits must be greater than 0"); return false; }
    if (parseFloat(form.per_resume_cost) < 0) { toast.error("Per resume cost cannot be negative"); return false; }
    return true;
  };

  const handleVerify = async (planId: string, productId: string) => {
    setVerifying(productId);
    try {
      const result = await syncDodoProduct("verify", { product_id: productId });
      setVerifyResults(prev => ({ ...prev, [productId]: result }));
      if (result.exists && result.is_active) {
        toast.success("Product verified on Dodo ✓");
      } else if (result.exists && !result.is_active) {
        toast.warning("Product exists on Dodo but is archived/inactive");
      } else {
        await supabase.from("plans").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", planId);
        qc.invalidateQueries({ queryKey: ["admin_plans"] });
        toast.error("Product not found on Dodo — link cleared automatically");
      }
    } catch (err: any) {
      toast.error("Verify failed: " + (err.message || "Unknown error"));
    } finally {
      setVerifying(null);
    }
  };

  const handleSyncToDodo = async (plan: any) => {
    setSaving(true);
    try {
      const dodoResult = await syncDodoProduct("create", {
        name: plan.name,
        price: plan.price,
        credits: plan.credits,
        billing_type: plan.billing_type,
        description: plan.description || "",
      });
      if (dodoResult.product_id) {
        const updateData: any = { dodo_product_id: dodoResult.product_id };
        if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
        await supabase.from("plans").update(updateData).eq("id", plan.id);
        toast.success("Plan synced with Dodo ✓");
        qc.invalidateQueries({ queryKey: ["admin_plans"] });
      }
    } catch (err: any) {
      toast.error("Dodo sync failed: " + (err.message || "Unknown error"));
    } finally {
      setSaving(false);
    }
  };

  const save = async () => {
    if (!validate()) return;
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        price: parseFloat(form.price),
        credits: parseInt(form.credits),
        billing_type: form.billing_type,
        active: form.active,
        per_resume_cost: parseFloat(form.per_resume_cost),
      } as any;

      if (editPlan === "new") {
        const { data: inserted, error } = await supabase.from("plans").insert(payload).select().single();
        if (error) { toast.error(error.message); return; }

        try {
          const dodoResult = await syncDodoProduct("create", {
            name: form.name.trim(),
            price: parseFloat(form.price),
            credits: parseInt(form.credits),
            billing_type: form.billing_type,
            description: form.description,
          });
          const dodoProductId = dodoResult.product_id;
          if (dodoProductId) {
            const updateData: any = { dodo_product_id: dodoProductId };
            if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
            await supabase.from("plans").update(updateData).eq("id", inserted.id);
            toast.success("Plan saved & synced with Dodo ✓");
          } else {
            toast.success("Plan saved (Dodo sync returned no product ID)");
          }
        } catch (dodoErr: any) {
          console.error("Dodo sync failed:", dodoErr);
          toast.warning("Plan saved locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
        }
      } else {
        const { error } = await supabase.from("plans").update(payload).eq("id", editPlan.id);
        if (error) { toast.error(error.message); return; }

        if (editPlan.dodo_product_id) {
          try {
            const verification = await syncDodoProduct("verify", {
              product_id: editPlan.dodo_product_id,
            });

            if (!verification.exists) {
              await supabase.from("plans").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", editPlan.id);
              const recreated = await syncDodoProduct("create", {
                name: form.name.trim(),
                price: parseFloat(form.price),
                credits: parseInt(form.credits),
                billing_type: form.billing_type,
                description: form.description,
              });
              if (recreated.product_id) {
                const updateData: any = { dodo_product_id: recreated.product_id };
                if (recreated.credit_entitlement_id) updateData.dodo_credit_entitlement_id = recreated.credit_entitlement_id;
                await supabase.from("plans").update(updateData).eq("id", editPlan.id);
              }
              toast.success("Missing Dodo product was re-created and linked ✓");
            } else {
              const dodoResult = await syncDodoProduct("update", {
                product_id: editPlan.dodo_product_id,
                name: form.name.trim(),
                price: parseFloat(form.price),
                credits: parseInt(form.credits),
                billing_type: form.billing_type,
                description: form.description,
              });

              if (dodoResult.credit_entitlement_id) {
                await supabase.from("plans").update({ dodo_credit_entitlement_id: dodoResult.credit_entitlement_id }).eq("id", editPlan.id);
              }
              toast.success("Plan updated & synced with Dodo ✓");
            }
          } catch (dodoErr: any) {
            console.error("Dodo sync failed:", dodoErr);
            toast.warning("Plan updated locally but Dodo sync failed: " + (dodoErr.message || "Unknown error"));
          }
        } else {
          try {
            const dodoResult = await syncDodoProduct("create", {
              name: form.name.trim(),
              price: parseFloat(form.price),
              credits: parseInt(form.credits),
              billing_type: form.billing_type,
              description: form.description,
            });
            const dodoProductId = dodoResult.product_id;
            if (dodoProductId) {
              const updateData: any = { dodo_product_id: dodoProductId };
              if (dodoResult.credit_entitlement_id) updateData.dodo_credit_entitlement_id = dodoResult.credit_entitlement_id;
              await supabase.from("plans").update(updateData).eq("id", editPlan.id);
              toast.success("Plan updated & linked to Dodo ✓");
            } else {
              toast.success("Plan updated");
            }
          } catch (dodoErr: any) {
            console.error("Dodo create failed:", dodoErr);
            toast.warning("Plan updated but Dodo link failed: " + (dodoErr.message || "Unknown error"));
          }
        }
      }

      logAuditAction(
        editPlan === "new" ? "plan.create" : "plan.update",
        "plan",
        editPlan === "new" ? undefined : editPlan.id,
        { name: form.name, price: form.price, credits: form.credits },
      );
      qc.invalidateQueries({ queryKey: ["admin_plans"] });
      setEditPlan(null);
    } finally {
      setSaving(false);
    }
  };

  const handleArchive = async (plan: any) => {
    if (plan.dodo_product_id) {
      try {
        const v = await syncDodoProduct("verify", { product_id: plan.dodo_product_id });
        if (v.exists) {
          await syncDodoProduct("deactivate", { product_id: plan.dodo_product_id, credit_entitlement_id: plan.dodo_credit_entitlement_id });
        } else {
          await supabase.from("plans").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", plan.id);
        }
      } catch { /* continue */ }
    }
    const { error } = await supabase.from("plans").update({ active: false }).eq("id", plan.id);
    if (error) { toast.error(error.message); return; }
    toast.success(`"${plan.name}" archived`);
    logAuditAction("plan.archive", "plan", plan.id, { name: plan.name });
    qc.invalidateQueries({ queryKey: ["admin_plans"] });
  };

  const handleRestore = async (plan: any) => {
    if (plan.dodo_product_id) {
      try {
        const v = await syncDodoProduct("verify", { product_id: plan.dodo_product_id });
        if (v.exists) {
          await syncDodoProduct("reactivate", { product_id: plan.dodo_product_id, credit_entitlement_id: plan.dodo_credit_entitlement_id });
        } else {
          await supabase.from("plans").update({ dodo_product_id: null, dodo_credit_entitlement_id: null }).eq("id", plan.id);
          toast.info("Stale Dodo link cleared — you can re-sync after restore.");
        }
      } catch { /* continue */ }
    }
    const { error } = await supabase.from("plans").update({ active: true }).eq("id", plan.id);
    if (error) { toast.error(error.message); return; }
    toast.success(`"${plan.name}" restored`);
    logAuditAction("plan.restore", "plan", plan.id, { name: plan.name });
    qc.invalidateQueries({ queryKey: ["admin_plans"] });
  };

  const confirmDelete = async () => {
    if (!deleteTarget) return;
    const count = paymentCounts?.[deleteTarget.id] || 0;
    if (count > 0) {
      toast.error(`Cannot delete — this plan has ${count} payment(s) linked. It will remain archived.`);
      setDeleteTarget(null);
      return;
    }

    if (deleteTarget.dodo_product_id) {
      try {
        await syncDodoProduct("deactivate", { product_id: deleteTarget.dodo_product_id, credit_entitlement_id: deleteTarget.dodo_credit_entitlement_id });
      } catch { /* continue */ }
    }

    const { error } = await supabase.from("plans").delete().eq("id", deleteTarget.id);
    if (error) {
      const message = (error as any)?.message ?? "";
      const code = (error as any)?.code;
      if (code === "23503" || /foreign key/i.test(message)) {
        toast.error("Cannot delete — this plan has existing payments linked to it.");
      } else {
        toast.error(message || "Failed to delete");
      }
      setDeleteTarget(null);
      return;
    }
    toast.success("Plan permanently deleted");
    logAuditAction("plan.delete", "plan", deleteTarget.id, { name: deleteTarget.name });
    qc.invalidateQueries({ queryKey: ["admin_plans"] });
    setDeleteTarget(null);
  };

  const DodoBadge = ({ p }: { p: any }) => {
    const vr = verifyResults[p.dodo_product_id];
    if (!p.dodo_product_id) {
      return (
        <Button variant="ghost" size="sm" className="h-6 px-2 gap-1 text-[10px]" onClick={() => handleSyncToDodo(p)} disabled={saving}>
          <Link2 className="h-3 w-3 text-amber-500" />
          <span className="text-muted-foreground">Sync to Dodo</span>
        </Button>
      );
    }
    return (
      <Button
        variant="ghost"
        size="sm"
        className="h-6 px-2 gap-1 text-[10px]"
        onClick={() => handleVerify(p.id, p.dodo_product_id)}
        disabled={verifying === p.dodo_product_id}
      >
        {verifying === p.dodo_product_id ? (
          <Loader2 className="h-3 w-3 animate-spin" />
        ) : vr ? (
          vr.exists && vr.is_active ? <CheckCircle className="h-3 w-3 text-emerald-600" /> :
          vr.exists ? <AlertTriangle className="h-3 w-3 text-amber-500" /> :
          <AlertTriangle className="h-3 w-3 text-destructive" />
        ) : (
          <CheckCircle className="h-3 w-3 text-emerald-600" />
        )}
        <span>{vr ? (vr.exists && vr.is_active ? "Verified ✓" : vr.exists ? "Inactive on Dodo" : "Not found") : "Linked"}</span>
        <RefreshCw className="h-2.5 w-2.5 text-muted-foreground" />
      </Button>
    );
  };

  const PlanRow = ({ p, archived = false }: { p: any; archived?: boolean }) => {
    const count = paymentCounts?.[p.id] || 0;
    return (
      <TableRow key={p.id} className={archived ? "opacity-60" : ""}>
        <TableCell className="font-medium">
          <div className="flex items-center gap-2">
            {p.name}
            {archived && <Badge variant="outline" className="text-[10px] text-muted-foreground">Archived</Badge>}
          </div>
        </TableCell>
        <TableCell>${p.price}</TableCell>
        <TableCell>{p.credits}</TableCell>
        <TableCell>${p.per_resume_cost ?? "0.05"}</TableCell>
        <TableCell>{p.billing_type}</TableCell>
        <TableCell><DodoBadge p={p} /></TableCell>
        <TableCell className="flex gap-1">
          {archived ? (
            <>
              <Button variant="ghost" size="icon" title="Restore" onClick={() => handleRestore(p)}>
                <RotateCcw className="h-3.5 w-3.5 text-primary" />
              </Button>
              <Button
                variant="ghost"
                size="icon"
                title={count > 0 ? `${count} payment(s) linked — cannot delete` : "Delete permanently"}
                onClick={() => setDeleteTarget({ id: p.id, name: p.name, dodo_product_id: p.dodo_product_id, dodo_credit_entitlement_id: p.dodo_credit_entitlement_id, paymentCount: count })}
              >
                <Trash2 className={`h-3.5 w-3.5 ${count > 0 ? "text-muted-foreground" : "text-destructive"}`} />
              </Button>
              {count > 0 && <span className="text-[10px] text-destructive self-center">{count} payments</span>}
            </>
          ) : (
            <>
              <Button variant="ghost" size="icon" onClick={() => openEdit(p)}><Pencil className="h-3.5 w-3.5" /></Button>
              <Button variant="ghost" size="icon" title="Archive" onClick={() => handleArchive(p)}>
                <Archive className="h-3.5 w-3.5 text-muted-foreground" />
              </Button>
            </>
          )}
        </TableCell>
      </TableRow>
    );
  };

  return (
    <>
      <Card>
        <CardHeader className="flex flex-row items-center justify-between pb-3">
          <CardTitle className="text-lg">Subscription Plans</CardTitle>
          <Dialog open={editPlan !== null} onOpenChange={(o) => !o && setEditPlan(null)}>
            <DialogTrigger asChild>
              <Button size="sm" onClick={openNew}><Plus className="h-4 w-4 mr-1" />Add Plan</Button>
            </DialogTrigger>
            <DialogContent aria-describedby="plan-dialog-desc">
              <DialogHeader>
                <DialogTitle>{editPlan === "new" ? "New Plan" : "Edit Plan"}</DialogTitle>
                <DialogDescription id="plan-dialog-desc">
                  {editPlan === "new" ? "Create a new subscription plan synced with Dodo Payments." : "Update this plan. Changes sync automatically with Dodo."}
                </DialogDescription>
              </DialogHeader>
              <div className="space-y-3">
                <div><Label>Name</Label><Input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="e.g. Pro Monthly" /></div>
                <div><Label>Description</Label><Textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} placeholder="Brief plan description (shown on Dodo)" rows={2} /></div>
                <div className="grid grid-cols-2 gap-3">
                  <div><Label>Price ($)</Label><Input type="number" min="0.01" step="0.01" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /></div>
                  <div><Label>Credits</Label><Input type="number" min="1" value={form.credits} onChange={(e) => setForm({ ...form, credits: e.target.value })} /></div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div><Label>Billing Type</Label><Input value={form.billing_type} onChange={(e) => setForm({ ...form, billing_type: e.target.value })} /></div>
                  <div><Label>Per Resume Cost ($)</Label><Input type="number" step="0.01" min="0" value={form.per_resume_cost} onChange={(e) => setForm({ ...form, per_resume_cost: e.target.value })} /></div>
                </div>
                <div className="flex items-center gap-2"><Switch checked={form.active} onCheckedChange={(c) => setForm({ ...form, active: c })} /><Label>Active</Label></div>

                {/* Dodo IDs (read-only when editing) */}
                {editPlan && editPlan !== "new" && (editPlan.dodo_product_id || editPlan.dodo_credit_entitlement_id) && (
                  <div className="bg-muted/50 rounded-md px-3 py-2 space-y-1">
                    <p className="text-[10px] font-medium text-muted-foreground uppercase tracking-wider">Dodo Integration</p>
                    {editPlan.dodo_product_id && (
                      <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                        <span>Product:</span>
                        <code className="bg-background px-1.5 py-0.5 rounded text-[10px] font-mono">{editPlan.dodo_product_id}</code>
                        <a href={`https://app.dodopayments.com/products/edit?id=${editPlan.dodo_product_id}`} target="_blank" rel="noopener noreferrer">
                          <ExternalLink className="h-3 w-3 text-primary" />
                        </a>
                      </div>
                    )}
                    {editPlan.dodo_credit_entitlement_id && (
                      <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
                        <span>Credit Entitlement:</span>
                        <code className="bg-background px-1.5 py-0.5 rounded text-[10px] font-mono">{editPlan.dodo_credit_entitlement_id}</code>
                      </div>
                    )}
                  </div>
                )}

                <p className="text-xs text-muted-foreground bg-muted rounded-md px-3 py-2">
                  Dodo product will be auto-created/synced when you save. Brand "Rankora" is auto-attached.
                </p>
                <Button onClick={save} className="w-full" disabled={saving}>
                  {saving ? <Loader2 className="h-4 w-4 mr-1 animate-spin" /> : <Save className="h-4 w-4 mr-1" />}
                  {saving ? "Saving & Syncing..." : "Save"}
                </Button>
              </div>
            </DialogContent>
          </Dialog>
        </CardHeader>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Name</TableHead>
                <TableHead>Price</TableHead>
                <TableHead>Credits</TableHead>
                <TableHead>$/Resume</TableHead>
                <TableHead>Billing</TableHead>
                <TableHead>Dodo</TableHead>
                <TableHead></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {activePlans.length === 0 && archivedPlans.length === 0 && (
                <TableRow><TableCell colSpan={7} className="text-center text-muted-foreground py-8">No plans yet</TableCell></TableRow>
              )}
              {activePlans.map((p: any) => <PlanRow key={p.id} p={p} />)}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {archivedPlans.length > 0 && (
        <Card className="border-dashed">
          <CardHeader className="pb-3">
            <button
              onClick={() => setShowArchived(!showArchived)}
              className="flex items-center gap-2 text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
            >
              <Archive className="h-4 w-4" />
              Archived Plans ({archivedPlans.length})
              <span className="text-xs">{showArchived ? "▾" : "▸"}</span>
            </button>
          </CardHeader>
          {showArchived && (
            <CardContent className="p-0">
              <Table>
                <TableBody>
                  {archivedPlans.map((p: any) => <PlanRow key={p.id} p={p} archived />)}
                </TableBody>
              </Table>
            </CardContent>
          )}
        </Card>
      )}

      <ConfirmDialog
        open={deleteTarget !== null}
        onOpenChange={(o) => !o && setDeleteTarget(null)}
        title="Permanently Delete Plan"
        description={
          deleteTarget?.paymentCount && deleteTarget.paymentCount > 0
            ? `Cannot delete "${deleteTarget?.name}" — it has ${deleteTarget.paymentCount} payment(s) linked. It will remain in the archive.`
            : `Are you sure you want to permanently delete "${deleteTarget?.name}"? This cannot be undone.`
        }
        confirmLabel={deleteTarget?.paymentCount && deleteTarget.paymentCount > 0 ? "Understood" : "Delete Permanently"}
        onConfirm={deleteTarget?.paymentCount && deleteTarget.paymentCount > 0 ? () => setDeleteTarget(null) : confirmDelete}
      />
    </>
  );
};

export default PlansTab;

