218→
219→  // ── Analyze JD ──────────────────────────────────────────────
220→  const analyzeJd = async (jobId: string) => {
221→    setAnalyzingJd(true);
222→    try {
223→      const response = await fetch(
224→        `https://zkzontawprihrzpayeam.supabase.co/functions/v1/analyze-jd`,
225→        {
226→          method: "POST",
227→          headers: {
228→            "Content-Type": "application/json",
