300→  const handleRankingError = (err: any) => {
301→    const msg: string = err?.message || "Ranking failed.";
302→    if (msg.includes("Insufficient credits") || err?.status === 402) {
303→      setRankingError({ type: "credits", message: "You don't have enough credits to rank these resumes." });
304→    } else if (msg.includes("Rate limit") || err?.status === 429) {
