321→  const handleRankNew = async () => {
322→    if (!user) return;
323→    const filesToRank = [...files];
324→    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
325→    setRanking(true); setResults([]); setRankingError(null);
326→    setRankingProgress(5); setScoredCount(0); setTotalToScore(filesToRank.length);
327→
328→    try {
329→      const autoTitle = (() => {
330→        const firstLine = jobDescription.trim().split("\n")[0].trim();
331→        return firstLine.slice(0, 50).trim() || `Job - ${new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`;
332→      })();
333→
334→      const { data: job, error: jobError } = await supabase
335→        .from("jobs")
336→        .insert({ user_id: user.id, job_description: jobDescription, status: "pending", title: autoTitle } as any)
337→        .select("id, inbox_email")
