339→      if (jobError || !job) throw new Error(jobError?.message || "Failed to create job");
340→      setRankingProgress(10);
341→
342→      const analysisData = await analyzeJd(job.id);
343→      setRankingProgress(25);
344→
345→      onJobCreated({
346→        id: job.id,
