353→        dynamic_weights_json: analysisData.dynamic_weights,
354→        inbox_email: job.inbox_email ?? null,
355→      });
356→
357→      const resumeIds = await uploadFilesFromSnapshot(job.id, filesToRank);
358→      setRankingProgress(40);
359→
360→      await rankAndPoll(job.id, resumeIds);
361→
362→      setJobDescription("");
363→      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
364→      toast.success("Candidates ranked!");
365→    } catch (err: any) {
366→      handleRankingError(err);
367→    } finally {
368→      rankingFilesRef.current = new Set();
369→      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
