385→      }
386→
387→      const resumeIds = await uploadFilesFromSnapshot(selectedJobId, filesToRank);
388→      setRankingProgress(40);
389→
390→      await rankAndPoll(selectedJobId, resumeIds);
391→
392→      const { data: allResumes } = await supabase
393→        .from("resumes")
394→        .select("id, filename, file_path, candidate_name, created_at")
