402→      handleRankingError(err);
403→    } finally {
404→      rankingFilesRef.current = new Set();
405→      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
406→      autoRankTriggered.current = false;
407→    }
408→  };
409→
410→  const uploadFilesFromSnapshot = async (jobId: string, filesToUpload: UploadedFile[]): Promise<string[]> => {
411→    if (!user) return [];
412→    const resumeIds: string[] = [];
413→    for (const { file, name } of filesToUpload) {
414→      const filePath = `${user.id}/${jobId}/${Date.now()}_${name}`;
415→      const { error: uploadError } = await supabase.storage.from("resumes").upload(filePath, file);
416→      if (uploadError) throw new Error(`Upload failed: ${uploadError.message}`);
417→      const { data: resume, error: resumeError } = await supabase
418→        .from("resumes")
419→        .insert({ job_id: jobId, filename: name, file_path: filePath })
420→        .select("id")
421→        .single();
422→      if (resumeError || !resume) throw new Error(resumeError?.message || "Failed to save resume");
423→      resumeIds.push(resume.id);
424→    }
425→    return resumeIds;
