                      <AlertTriangle className="h-3 w-3" />
                    ) : (
                      <Wallet className="h-3 w-3" />
                    )}
                  </div>
                  <div className="flex flex-col items-start leading-none">
                    <span className="text-sm font-bold tabular-nums">{totalCredits}</span>
                    <span className={`text-[10px] font-medium ${isLowCredits ? "text-destructive/70" : "text-primary/60"}`}>credits</span>
                  </div>
                </button>

                {/* User avatar dropdown */}
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
