import { useState, useCallback, useRef, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { usePlatformConfig } from "@/hooks/usePlatformConfig";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Progress } from "@/components/ui/progress";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle
} from "@/components/ui/alert-dialog";
import { toast } from "sonner";
import {
  Upload, Copy, Loader2, FileText,
  AlertTriangle, X, Trash2, RefreshCw, CheckCircle2, FileSpreadsheet,
  Brain, ListChecks, BarChart2, ArrowRight, Sparkles, Clock, Users, Star, Mail, Zap,
  Archive, ArchiveRestore, FolderOpen, Wand2, Pencil
} from "lucide-react";
import { exportToCSV } from "@/lib/csvExport";
import CandidateRow from "@/components/CandidateRow";
import JDRewriteDialog from "@/components/JDRewriteDialog";
import ScoreSummaryCards from "@/components/ScoreSummaryCards";
import ConfidenceReport from "@/components/ConfidenceReport";
import type { PastJob, Result, ExistingResume } from "@/pages/Index";
import { useStages, useUpdateStage, useStageSummary, STAGE_ORDER, type HiringStage } from "@/hooks/useStageTracker";

interface JobDetailViewProps {
  selectedJobId: string | null;
  selectedJob: PastJob | null;
  results: Result[];
  setResults: (results: Result[] | ((prev: Result[]) => Result[])) => void;
  existingResumes: ExistingResume[];
  setExistingResumes: (resumes: ExistingResume[] | ((prev: ExistingResume[]) => ExistingResume[])) => void;
  onJobCreated: (job: PastJob) => void;
  onAuthRequired: () => void;
  onJobUpdated?: (jobId: string, updates: Partial<PastJob>) => void;
  isAuthenticated?: boolean;
}

interface UploadedFile {
  file: File;
  name: string;
}

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const JobDetailView = ({
  selectedJobId,
  selectedJob,
  results,
  setResults,
  existingResumes,
  setExistingResumes,
  onJobCreated,
  onAuthRequired,
  onJobUpdated,
  isAuthenticated = true,
}: JobDetailViewProps) => {
  const { user, profile, refreshProfile } = useAuth();
  const { data: config } = usePlatformConfig();

  const [jobDescription, setJobDescription] = useState("");
  const [files, setFiles] = useState<UploadedFile[]>([]);
  const [ranking, setRanking] = useState(false);
  const [rankingProgress, setRankingProgress] = useState(0);
  const [scoredCount, setScoredCount] = useState(0);
  const [totalToScore, setTotalToScore] = useState(0);
  const [expandedRows, setExpandedRows] = useState<Set<string>>(new Set());
  const [dragOver, setDragOver] = useState(false);
  const [rankingError, setRankingError] = useState<{ type: "credits" | "rate_limit" | "generic"; message: string } | null>(null);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [selectedResumes, setSelectedResumes] = useState<Set<string>>(new Set());
  const [deleteConfirm, setDeleteConfirm] = useState<{type: "single" | "bulk"; resumeId?: string; filePath?: string | null;} | null>(null);
  const [deleting, setDeleting] = useState(false);
  const [analyzingJd, setAnalyzingJd] = useState(false);
  const [dismissedResumes, setDismissedResumes] = useState<Set<string>>(() => new Set());
  const [showArchived, setShowArchived] = useState(false);
  const [stageFilter, setStageFilter] = useState<HiringStage | null>(null);
  const [jdRewriteOpen, setJdRewriteOpen] = useState(false);
  const [stuckJobDetected, setStuckJobDetected] = useState(false);
  const [retrying, setRetrying] = useState(false);
  const [editingJd, setEditingJd] = useState(false);
  const [editedJdText, setEditedJdText] = useState("");
  const [confirmEditJdOpen, setConfirmEditJdOpen] = useState(false);

  const resultsRef = useRef<HTMLDivElement>(null);
  const rankingFilesRef = useRef<Set<string>>(new Set());
  const activeJobRef = useRef<string | null>(selectedJobId);
  const maxResumes = config?.max_resumes_per_job ?? 10;
  const maxFileSizeMb = config?.max_file_size_mb ?? 5;

  const isNewJobMode = selectedJobId === null;
  const isExistingJob = selectedJobId !== null && selectedJob !== null;

  // Hiring Stage Tracker
  const { data: stages } = useStages(selectedJobId);
  const updateStageMutation = useUpdateStage();
  const stageSummary = useStageSummary(selectedJobId);
  const stageMap = new Map((stages ?? []).map((s) => [s.resume_id, s]));

  const handleStageChange = (resumeId: string, newStage: HiringStage) => {
    if (!selectedJobId) return;
    const current = stageMap.get(resumeId);
    updateStageMutation.mutate({
      resumeId,
      jobId: selectedJobId,
      newStage,
      currentStage: current?.stage,
    });
  };

  const formatCandidateName = (filename: string) => {
    const name = filename.replace(/\.\w+$/, "");
    if (UUID_REGEX.test(name)) return `Resume ${name.slice(0, 6).toUpperCase()}`;
    return name.replace(/[-_]/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
  };

  // Merge unranked resumes
  const resultResumeIds = new Set(results.map((r) => r.resume_id));
  const pendingResumes: Result[] = existingResumes
    .filter((r) => !resultResumeIds.has(r.id))
    .map((r) => ({
      id: `pending-${r.id}`,
      resume_id: r.id,
      overall_score: 0,
      missing_skills: [], summary: null, interview_questions: null,
      filename: r.filename, file_path: r.file_path, candidate_name: r.candidate_name,
      pending: true,
    }));
  const allResults = [...results, ...pendingResumes];

  // Selection helpers
  const toggleSelectResume = (resumeId: string) => {
    setSelectedResumes((prev) => {
      const next = new Set(prev);
      if (next.has(resumeId)) next.delete(resumeId); else next.add(resumeId);
      return next;
    });
  };
  const toggleSelectAll = () => {
    if (selectedResumes.size === allResults.length) setSelectedResumes(new Set());
    else setSelectedResumes(new Set(allResults.map((r) => r.resume_id)));
  };

  // Delete logic
  const deleteResume = async (resumeId: string, filePath: string | null) => {
    if (filePath) await supabase.storage.from("resumes").remove([filePath]);
    await supabase.from("results").delete().eq("resume_id", resumeId);
    await supabase.from("resumes").delete().eq("id", resumeId);
    setResults((prev: Result[]) => prev.filter((r) => r.resume_id !== resumeId));
    setExistingResumes((prev: ExistingResume[]) => prev.filter((r) => r.id !== resumeId));
    setSelectedResumes((prev) => { const next = new Set(prev); next.delete(resumeId); return next; });
  };

  const handleDeleteConfirm = async () => {
    if (!deleteConfirm) return;
    setDeleting(true);
    try {
      if (deleteConfirm.type === "single" && deleteConfirm.resumeId) {
        await deleteResume(deleteConfirm.resumeId, deleteConfirm.filePath ?? null);
        toast.success("Resume deleted");
      } else if (deleteConfirm.type === "bulk") {
        const toDelete = allResults.filter((r) => selectedResumes.has(r.resume_id));
        for (const r of toDelete) await deleteResume(r.resume_id, r.file_path);
        toast.success(`${toDelete.length} resume(s) deleted`);
      }
    } catch { toast.error("Failed to delete"); }
    finally { setDeleting(false); setDeleteConfirm(null); }
  };

  // File handling
  const handleFileDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault(); setDragOver(false);
    const dropped = Array.from(e.dataTransfer.files).filter(
      (f) => f.type === "application/pdf" || f.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    );
    addFiles(dropped);
  }, [files, maxResumes, maxFileSizeMb]);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) addFiles(Array.from(e.target.files));
  };

  const addFiles = (newFiles: File[]) => {
    const currentCount = isExistingJob ? existingResumes.length + files.length : files.length;
    const valid = newFiles.filter((f) => {
      if (f.size > maxFileSizeMb * 1024 * 1024) { toast.error(`${f.name} exceeds ${maxFileSizeMb}MB limit`); return false; }
      return true;
    });
    const remaining = maxResumes - currentCount;
    if (valid.length > remaining) toast.error(`Max ${maxResumes} resumes per job`);
    const toAdd = valid.slice(0, Math.max(0, remaining)).map((f) => ({ file: f, name: f.name }));
    setFiles((prev) => [...prev, ...toAdd]);
  };

  const removeFile = (index: number) => setFiles((prev) => prev.filter((_, i) => i !== index));
  const toggleRow = (id: string) => {
    setExpandedRows((prev) => { const next = new Set(prev); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  };

  const copyInboxEmail = () => {
    if (profile?.inbox_email) { navigator.clipboard.writeText(profile.inbox_email); toast.success("Inbox email copied!"); }
  };

  const validate = (): string[] => {
    const errors: string[] = [];
    if (isNewJobMode && !jobDescription.trim()) errors.push("Job description is required.");
    const filesToCheck = files.filter(f => !rankingFilesRef.current.has(f.name));
    if (filesToCheck.length === 0) errors.push("Upload at least one resume.");
    const splitTotal = (profile?.subscription_credits ?? 0) + (profile?.topup_credits ?? 0);
    const totalCredits = splitTotal > 0 ? splitTotal : (profile?.credits ?? 0);
    if (user && totalCredits < Math.min(filesToCheck.length, maxResumes)) {
      errors.push(`Not enough credits. You need ${Math.min(filesToCheck.length, maxResumes)} but have ${totalCredits}.`);
    }
    return errors;
  };

  // ── Analyze JD ──────────────────────────────────────────────
  const analyzeJd = async (jobId: string) => {
    setAnalyzingJd(true);
    try {
      const { data, error: invokeError } = await supabase.functions.invoke("analyze-jd", {
        body: { job_id: jobId },
      });
      if (invokeError) throw new Error(invokeError.message || "JD analysis failed");
      if (data?.error) throw new Error(data.error);
      if (onJobUpdated) {
        onJobUpdated(jobId, {
          jd_analysis_json: data.jd_analysis,
          dynamic_weights_json: data.dynamic_weights,
        });
      }
      return data;
    } catch (err: any) {
      toast.error(err.message || "JD analysis failed");
      throw err;
    } finally {
      setAnalyzingJd(false);
    }
  };

  // ── Reset all transient state when switching jobs ──
  useEffect(() => {
    activeJobRef.current = selectedJobId;
    setFiles([]);
    setRanking(false);
    setRankingProgress(0);
    setScoredCount(0);
    setTotalToScore(0);
    setExpandedRows(new Set());
    setValidationErrors([]);
    setRankingError(null);
    setAnalyzingJd(false);
    setStuckJobDetected(false);
    setSelectedResumes(new Set());
    setShowArchived(false);
    setStageFilter(null);
    setEditingJd(false);
    setEditedJdText("");
    rankingFilesRef.current = new Set();
    autoRankTriggered.current = false;
    if (selectedJobId) {
      try {
        const stored = localStorage.getItem(`dismissed_${selectedJobId}`);
        if (stored) {
          setDismissedResumes(new Set(JSON.parse(stored) as string[]));
        } else {
          setDismissedResumes(new Set());
        }
      } catch {
        setDismissedResumes(new Set());
      }
    } else {
      setDismissedResumes(new Set());
    }
  }, [selectedJobId]);

  // ── Auto-rank ───────────────────────────────────────────────
  const autoRankTriggered = useRef(false);
  useEffect(() => {
    const unrankedFiles = files.filter(f => !rankingFilesRef.current.has(f.name));
    if (unrankedFiles.length > 0 && !ranking && !autoRankTriggered.current) {
      if (isNewJobMode && !jobDescription.trim()) return;
      autoRankTriggered.current = true;
      handleRankClick();
    }
    if (files.length === 0 && !ranking) autoRankTriggered.current = false;
  }, [files, ranking, isNewJobMode, jobDescription]);

  const handleRankingError = (err: any) => {
    const msg: string = err?.message || "Ranking failed.";
    if (msg.includes("Insufficient credits") || err?.status === 402) {
      setRankingError({ type: "credits", message: "You don't have enough credits to rank these resumes." });
    } else if (msg.includes("Rate limit") || err?.status === 429) {
      setRankingError({ type: "rate_limit", message: "Too many jobs in a short time. Please wait a minute and try again." });
    } else {
      setRankingError({ type: "generic", message: msg });
      toast.error(msg);
    }
  };

  const handleRankClick = () => {
    if (!user) { onAuthRequired(); return; }
    setRankingError(null);
    const errors = validate();
    setValidationErrors(errors);
    if (errors.length > 0) return;
    if (isExistingJob) handleRankExisting(); else handleRankNew();
  };

  const handleRankNew = async () => {
    if (!user) return;
    const filesToRank = [...files];
    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
    setRanking(true); setResults([]); setRankingError(null);
    setRankingProgress(5); setScoredCount(0); setTotalToScore(filesToRank.length);

    try {
      const autoTitle = (() => {
        const firstLine = jobDescription.trim().split("\n")[0].trim();
        return firstLine.slice(0, 50).trim() || `Job - ${new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })}`;
      })();

      const { data: job, error: jobError } = await supabase
        .from("jobs")
        .insert({ user_id: user.id, job_description: jobDescription, status: "pending", title: autoTitle } as any)
        .select("id, inbox_email")
        .single();
      if (jobError || !job) throw new Error(jobError?.message || "Failed to create job");
      setRankingProgress(10);

      const analysisData = await analyzeJd(job.id);
      setRankingProgress(25);

      onJobCreated({
        id: job.id,
        title: autoTitle,
        job_description: jobDescription,
        status: "processing",
        created_at: new Date().toISOString(),
        resume_count: filesToRank.length,
        jd_analysis_json: analysisData.jd_analysis,
        dynamic_weights_json: analysisData.dynamic_weights,
        inbox_email: job.inbox_email ?? null,
      });

      const resumeIds = await uploadFilesFromSnapshot(job.id, filesToRank);
      setRankingProgress(40);

      await rankAndPoll(job.id, resumeIds);

      setJobDescription("");
      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
      toast.success("Candidates ranked!");
    } catch (err: any) {
      handleRankingError(err);
    } finally {
      rankingFilesRef.current = new Set();
      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
      autoRankTriggered.current = false;
    }
  };

  const handleRankExisting = async () => {
    if (!user || !selectedJobId) return;
    const filesToRank = [...files];
    rankingFilesRef.current = new Set(filesToRank.map(f => f.name));
    setRanking(true); setRankingError(null);
    setRankingProgress(10); setScoredCount(0); setTotalToScore(filesToRank.length);

    try {
      if (!selectedJob?.jd_analysis_json) {
        await analyzeJd(selectedJobId);
        setRankingProgress(25);
      }

      const resumeIds = await uploadFilesFromSnapshot(selectedJobId, filesToRank);
      setRankingProgress(40);

      await rankAndPoll(selectedJobId, resumeIds);

      const { data: allResumes } = await supabase
        .from("resumes")
        .select("id, filename, file_path, candidate_name, created_at")
        .eq("job_id", selectedJobId)
        .order("created_at", { ascending: false });
      if (allResumes) setExistingResumes(allResumes);

      setFiles(prev => prev.filter(f => !rankingFilesRef.current.has(f.name)));
      toast.success("New resumes ranked!");
    } catch (err: any) {
      handleRankingError(err);
    } finally {
      rankingFilesRef.current = new Set();
      setRanking(false); setRankingProgress(0); setScoredCount(0); setTotalToScore(0);
      autoRankTriggered.current = false;
    }
  };

  const uploadFilesFromSnapshot = async (jobId: string, filesToUpload: UploadedFile[]): Promise<string[]> => {
    if (!user) return [];
    const resumeIds: string[] = [];
    for (const { file, name } of filesToUpload) {
      const filePath = `${user.id}/${jobId}/${Date.now()}_${name}`;
      const { error: uploadError } = await supabase.storage.from("resumes").upload(filePath, file);
      if (uploadError) throw new Error(`Upload failed: ${uploadError.message}`);
      const { data: resume, error: resumeError } = await supabase
        .from("resumes")
        .insert({ job_id: jobId, filename: name, file_path: filePath })
        .select("id")
        .single();
      if (resumeError || !resume) throw new Error(resumeError?.message || "Failed to save resume");
      resumeIds.push(resume.id);
    }
    return resumeIds;
  };

  const rankAndPoll = async (jobId: string, resumeIds: string[]) => {
    const { data: rankData, error: rankError } = await supabase.functions.invoke("rank-resumes", {
      body: { job_id: jobId, resume_ids: resumeIds },
    });
    if (rankError) {
      const err: any = new Error(rankError.message || "Ranking failed");
      err.status = 500;
      throw err;
    }
    if (rankData?.error) {
      const err: any = new Error(rankData.error);
      err.status = rankData.status || 500;
      throw err;
    }
    setRankingProgress(60);

    for (let i = 0; i < 150; i++) {
      await new Promise((r) => setTimeout(r, 2000));
      // Stop polling if user switched to a different job
      if (activeJobRef.current !== jobId) return;
      const { data: resumeProgress } = await supabase.from("resumes").select("id, status").in("id", resumeIds);
      if (resumeProgress) {
        const done = resumeProgress.filter((r: any) => r.status === "done" || r.status === "failed").length;
        setScoredCount(done);
        const pct = resumeIds.length > 0 ? Math.round((done / resumeIds.length) * 35) : 0;
        setRankingProgress(Math.min(60 + pct, 95));
      }

      const { data: jobData } = await supabase.from("jobs").select("status, processing_started_at").eq("id", jobId).single();

      // Stuck-job detection: if processing for > 5 minutes
      if (jobData?.status === "processing" && jobData?.processing_started_at) {
        const elapsed = Date.now() - new Date(jobData.processing_started_at).getTime();
        if (elapsed > 5 * 60 * 1000) {
          setStuckJobDetected(true);
          setRanking(false);
          setRankingProgress(0);
          return;
        }
      }

      if (jobData?.status === "completed") {
         const { data: allResumes } = await supabase.from("resumes").select("id, filename, file_path, candidate_name, parsed_json").eq("job_id", jobId);
         if (allResumes) {
           const allResumeIds = allResumes.map((r: any) => r.id);
            const { data: resultData } = await supabase
              .from("results")
              .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
              .in("resume_id", allResumeIds);

            const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
            const allMerged: Result[] = (resultData ?? []).map((r: any) => {
              const resume = resumeMap.get(r.resume_id);
              const parsed = resume?.parsed_json as any;
              return {
                ...r,
                overall_score: r.overall_score ?? 0,
                missing_skills: r.missing_skills ?? [],
                filename: resume?.filename ?? "Unknown",
                file_path: resume?.file_path ?? null,
                candidate_name: resume?.candidate_name ?? null,
                candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
                candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
                candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
                parsed_json: resume?.parsed_json ?? null,
              };
            });
          // Deduplicate by resume_id — keep highest score
          const deduped = new Map<string, Result>();
          for (const r of allMerged) {
            const existing = deduped.get(r.resume_id);
            if (!existing || r.overall_score > existing.overall_score) {
              deduped.set(r.resume_id, r);
            }
          }
          const merged = Array.from(deduped.values());
          merged.sort((a, b) => b.overall_score - a.overall_score);
          setResults(merged);
        }
        setStuckJobDetected(false);
        setRankingProgress(100);
        await refreshProfile();
        setTimeout(() => { resultsRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }); }, 200);
        return;
      }
      if (jobData?.status === "failed") throw new Error("Ranking failed on server");
    }
    throw new Error("Ranking timed out");
  };

  const handleRetryStuck = async () => {
    if (!user || !selectedJobId) return;
    setRetrying(true);
    setStuckJobDetected(false);
    try {
      // Find resumes that haven't been scored yet
      const { data: jobResumes } = await supabase.from("resumes").select("id, status").eq("job_id", selectedJobId);
      const unscoredIds = (jobResumes || [])
        .filter((r: any) => r.status !== "done")
        .map((r: any) => r.id);

      if (unscoredIds.length === 0) {
        // All resumes are actually done, just mark job completed
        await supabase.from("jobs").update({ status: "completed", completed_at: new Date().toISOString() }).eq("id", selectedJobId);
        toast.success("All resumes were already scored. Job marked complete.");
        // Re-fetch results
        const { data: allResumes } = await supabase.from("resumes").select("id, filename, file_path, candidate_name, parsed_json").eq("job_id", selectedJobId);
        if (allResumes) {
          const allResumeIds = allResumes.map((r: any) => r.id);
          const { data: resultData } = await supabase.from("results")
            .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
            .in("resume_id", allResumeIds);
          const resumeMap = new Map(allResumes.map((r: any) => [r.id, r]));
          const merged: Result[] = (resultData ?? []).map((r: any) => {
            const resume = resumeMap.get(r.resume_id);
            const parsed = resume?.parsed_json as any;
            return { ...r, overall_score: r.overall_score ?? 0, missing_skills: r.missing_skills ?? [], filename: resume?.filename ?? "Unknown", file_path: resume?.file_path ?? null, candidate_name: resume?.candidate_name ?? null, candidate_email: parsed?.email ?? parsed?.contact?.email ?? null, candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null, candidate_location: parsed?.location ?? parsed?.contact?.location ?? null, parsed_json: resume?.parsed_json ?? null };
          });
          merged.sort((a, b) => b.overall_score - a.overall_score);
          setResults(merged);
        }
      } else {
        // Reset stuck resumes to pending and retry
        for (const rid of unscoredIds) {
          await supabase.from("resumes").update({ status: "pending" }).eq("id", rid);
        }
        toast.info(`Retrying ${unscoredIds.length} unscored resume(s)...`);
        setRanking(true);
        setRankingProgress(40);
        await rankAndPoll(selectedJobId, unscoredIds);
        toast.success("Retry completed!");
      }
    } catch (err: any) {
      toast.error(err.message || "Retry failed");
    } finally {
      setRetrying(false);
      setRanking(false);
      setRankingProgress(0);
    }
  };

  const handleRerank = async () => {
    if (!user || !selectedJobId || existingResumes.length === 0) return;
    setRanking(true); setRankingProgress(10);
    try {
      if (!selectedJob?.jd_analysis_json) {
        await analyzeJd(selectedJobId);
        setRankingProgress(20);
      }
      const resumeIds = existingResumes.map((r) => r.id);
      await supabase.from("results").delete().in("resume_id", resumeIds);
      // Bump parse_version to force re-parsing but keep old data as fallback
      for (const rid of resumeIds) {
        await supabase.from("resumes").update({ parse_version: "force_reparse", status: "pending" } as any).eq("id", rid);
      }
      setRankingProgress(30);
      await supabase.from("jobs").update({ status: "processing" }).eq("id", selectedJobId);
      await rankAndPoll(selectedJobId, resumeIds);
      const { data: allResumes } = await supabase
        .from("resumes")
        .select("id, filename, file_path, candidate_name, created_at")
        .eq("job_id", selectedJobId)
        .order("created_at", { ascending: false });
      if (allResumes) setExistingResumes(allResumes);
      toast.success("All candidates re-ranked!");
    } catch (err: any) { toast.error(err.message || "Re-ranking failed."); }
    finally { setRanking(false); setRankingProgress(0); }
  };

  const downloadResume = async (filePath: string, filename: string) => {
    const { data, error } = await supabase.storage.from("resumes").download(filePath);
    if (error || !data) { toast.error("Download failed"); return; }
    const url = URL.createObjectURL(data);
    const a = document.createElement("a"); a.href = url; a.download = filename; a.click();
    URL.revokeObjectURL(url);
  };

  const deleteCount = deleteConfirm?.type === "bulk" ? selectedResumes.size : 1;

  const handleDismiss = (resumeId: string) => {
    setDismissedResumes((prev) => {
      const next = new Set(prev).add(resumeId);
      if (selectedJobId) {
        try {
          localStorage.setItem(`dismissed_${selectedJobId}`, JSON.stringify(Array.from(next)));
        } catch { /* ignore storage errors */ }
      }
      return next;
    });
    toast.success("Candidate archived");
  };

  const handleUnarchive = (resumeId: string) => {
    setDismissedResumes((prev) => {
      const next = new Set(prev);
      next.delete(resumeId);
      if (selectedJobId) {
        try {
          if (next.size === 0) {
            localStorage.removeItem(`dismissed_${selectedJobId}`);
          } else {
            localStorage.setItem(`dismissed_${selectedJobId}`, JSON.stringify(Array.from(next)));
          }
        } catch { /* ignore storage errors */ }
      }
      if (next.size === 0) setShowArchived(false);
      return next;
    });
    toast.success("Candidate restored");
  };

  const handleSaveJd = async () => {
    if (!selectedJobId) return;
    const trimmed = editedJdText.trim();
    if (!trimmed) { toast.error("Job description cannot be empty."); return; }
    try {
      const { error } = await supabase.from("jobs").update({ job_description: trimmed }).eq("id", selectedJobId);
      if (error) throw new Error(error.message);
      onJobUpdated?.(selectedJobId, { job_description: trimmed });
      toast.success("Job description updated");
      setEditingJd(false);
    } catch (err: any) {
      toast.error(err.message || "Failed to save job description");
    }
  };

  const nonArchivedResults = allResults.filter((r) => !dismissedResumes.has(r.resume_id));
  const visibleResults = nonArchivedResults.filter((r) => {
    if (!stageFilter) return true;
    const candidateStage = stageMap.get(r.resume_id)?.stage ?? "applied";
    return candidateStage === stageFilter;
  });
  const archivedResults = allResults.filter((r) => dismissedResumes.has(r.resume_id));

  // Accurate stage counts — un-staged candidates count as "applied"
  const effectiveStageCounts = (["applied", "screened", "interview", "offer", "hired", "rejected"] as const).reduce(
    (acc, stage) => {
      acc[stage] = nonArchivedResults.filter((r) => !r.pending && (stageMap.get(r.resume_id)?.stage ?? "applied") === stage).length;
      return acc;
    },
    {} as Record<HiringStage, number>
  );

  return (
    <div className="flex-1 overflow-auto">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">

        {/* Hero — only for new job / unauthenticated state */}
        {!isExistingJob && allResults.length === 0 && (
          <div className="text-center pt-2 pb-2">
            <div className="inline-flex items-center gap-1.5 bg-primary/10 text-primary text-xs font-semibold px-3 py-1 rounded-full mb-4">
              <Sparkles className="h-3.5 w-3.5" />
              Powered by GPT-4o
            </div>
            <h1 className="text-3xl sm:text-4xl font-extrabold text-foreground tracking-tight leading-tight mb-3">
              Rank resumes in{" "}
              <span className="text-primary">under 2 minutes</span>
            </h1>
            <p className="text-sm sm:text-base text-muted-foreground max-w-xl mx-auto leading-relaxed">
              Paste a job description, upload up to {maxResumes} resumes — AI scores every candidate with strengths, gaps, and interview questions. No setup needed.
            </p>
          </div>
        )}

        {/* Two-column: JD (left) + Right column (upload + inbox) */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:items-start">
          {/* LEFT — JD card stretches to match right column height via self-stretch */}
          <Card className="flex flex-col md:self-stretch">
            <CardHeader className="pb-3 shrink-0">
              <div className="flex items-center justify-between">
                <CardTitle className="text-lg">
                  {isExistingJob ? "Job Description" : "Paste Job Description"}
                </CardTitle>
                <div className="flex items-center gap-2">
                  {isExistingJob && selectedJob?.jd_analysis_json && (
                    <Badge variant="secondary" className="gap-1 text-[10px]">
                      <Zap className="h-2.5 w-2.5 text-primary" />
                      AI analyzed
                    </Badge>
                  )}
                  {isExistingJob && !editingJd && (
                    <Button
                      variant="outline"
                      size="sm"
                      className="gap-1.5 h-7 text-xs"
                      onClick={() => {
                        setEditedJdText(selectedJob?.job_description ?? "");
                        if (results.length > 0) {
                          setConfirmEditJdOpen(true);
                        } else {
                          setEditingJd(true);
                        }
                      }}
                    >
                      <Pencil className="h-3.5 w-3.5" />
                      Edit JD
                    </Button>
                  )}
                  {isExistingJob && editingJd && (
                    <>
                      <Button
                        size="sm"
                        className="gap-1.5 h-7 text-xs"
                        onClick={handleSaveJd}
                      >
                        Save
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        className="h-7 text-xs"
                        onClick={() => setEditingJd(false)}
                      >
                        Cancel
                      </Button>
                    </>
                  )}
                  {isExistingJob && !editingJd && selectedJob?.job_description && (
                    <Button
                      variant="outline"
                      size="sm"
                      className="gap-1.5 h-7 text-xs"
                      onClick={() => setJdRewriteOpen(true)}
                    >
                      <Wand2 className="h-3.5 w-3.5 text-primary" />
                      AI Rewrite JD
                    </Button>
                  )}
                </div>
              </div>
            </CardHeader>
            <CardContent className="flex flex-col flex-1 pb-4">
              {isExistingJob ? (
                editingJd ? (
                  <textarea
                    value={editedJdText}
                    onChange={(e) => setEditedJdText(e.target.value)}
                    className="flex-1 min-h-[240px] w-full resize-none rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-sm placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                    autoFocus
                  />
                ) : (
                  <div className="bg-muted/50 rounded-md p-4 text-sm whitespace-pre-wrap overflow-y-auto leading-relaxed flex-1 max-h-[400px]">
                    {selectedJob?.job_description}
                  </div>
                )
              ) : (
                <textarea
                  placeholder="Paste the full job description here…"
                  value={jobDescription}
                  onFocus={() => { if (!isAuthenticated) { onAuthRequired(); } }}
                  onChange={(e) => { if (!isAuthenticated) { onAuthRequired(); return; } setJobDescription(e.target.value); }}
                  className="flex-1 min-h-[240px] w-full resize-none rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-sm placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                />
              )}
            </CardContent>
          </Card>

          {/* RIGHT column — upload card + inbox email card, drives the row height */}
          <div className="flex flex-col gap-4">

            {/* Upload card */}
            <Card>
              <CardHeader className="pb-3">
                <div className="flex items-center justify-between">
                  <CardTitle className="text-lg">
                    {isExistingJob ? "Add More Resumes" : "Upload Resumes"}
                  </CardTitle>
                  {isExistingJob && existingResumes.length > 0 && (
                    <Badge variant="secondary" className="text-[10px]">
                      {existingResumes.length} uploaded
                    </Badge>
                  )}
                </div>
              </CardHeader>
              <CardContent className="space-y-3">
                <div
                  className={`border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-all duration-300 flex flex-col items-center justify-center ${
                    dragOver ? "border-primary bg-primary/5 scale-[1.01]" : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
                  }`}
                  onDragOver={(e) => { e.preventDefault(); if (!isAuthenticated) return; setDragOver(true); }}
                  onDragLeave={() => setDragOver(false)}
                  onDrop={(e) => { if (!isAuthenticated) { e.preventDefault(); onAuthRequired(); return; } handleFileDrop(e); }}
                  onClick={() => { if (!isAuthenticated) { onAuthRequired(); return; } document.getElementById("file-input")?.click(); }}
                >
                  <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center mb-2.5">
                    <Upload className="h-5 w-5 text-primary" />
                  </div>
                  <p className="text-sm font-medium text-foreground mb-1">Drop resumes here</p>
                  <p className="text-xs text-muted-foreground">PDF, DOCX, DOC, RTF, TXT · Max {maxResumes} files · {maxFileSizeMb}MB each</p>
                  <input id="file-input" type="file" className="hidden" multiple accept=".pdf,.docx,.doc,.rtf,.txt" onChange={handleFileSelect} />
                </div>
                {files.length > 0 && (
                  <div className="space-y-1.5">
                    {files.map((f, i) => {
                      const isProcessing = rankingFilesRef.current.has(f.name) && ranking;
                      return (
                        <div key={i} className="flex items-center justify-between bg-secondary/50 rounded-md px-3 py-2 animate-fade-in">
